import bisect

def table_zone_eval(zone, ops):
    # --- Validation ---
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple or list")
    initial, transitions = zone
    if type(initial) is not int or abs(initial) > 50400:
        raise ValueError("initial offset invalid")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list or tuple")

    times = []
    prev_t = -10**14
    prev_off = initial
    for i, item in enumerate(transitions):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("transition item must be a 2-tuple or list")
        t, off = item
        if type(t) is not int or type(off) is not int:
            raise ValueError("transition values must be ints")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("transition bounds exceeded")
        if i > 0 and t - prev_t < 172800:
            raise ValueError("transitions gap too small")
        if abs(off - prev_off) > 86400:
            raise ValueError("offset change too large")
        times.append(t)
        prev_t = t
        prev_off = off

    # --- Helper Functions ---
    def get_off(x):
        idx = bisect.bisect_right(times, x) - 1
        if idx < 0:
            return initial
        return transitions[idx][1]

    def resolve(w, fold):
        idx = bisect.bisect_right(times, w) - 1
        off = get_off(w)
        x0 = w - off
        if get_off(x0) == off:
            # Check for second match (fold)
            x1 = None
            if idx >= 0:
                t = times[idx]
                prev_o = transitions[idx-1][1] if idx > 0 else initial
                if w == t + prev_o:
                    x1 = t
            if x1 is not None and x1 != x0:
                return x1 if fold == 0 else x0
            return x0
        else:
            # 0 matches (gap)
            if idx < 0:
                raise ValueError("gap without transition")
            t = times[idx]
            a = transitions[idx-1][1] if idx > 0 else initial
            b = off
            return w - a if fold == 0 else w - b

    def wall(x):
        off = get_off(x)
        w = x + off
        idx = bisect.bisect_right(times, x) - 1
        f = 0
        if idx >= 0:
            t = times[idx]
            if t < x:
                prev_o = transitions[idx-1][1] if idx > 0 else initial
                if w == t + prev_o:
                    f = 1
        return (w, f)

    # --- Process Operations ---
    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op must be a list or tuple")
        if len(op) not in (2, 3, 5):
            raise ValueError("op length invalid")
        name = op[0]
        if name == "instant":
            if len(op) != 3: raise ValueError()
            w, fold = op[1], op[2]
            if type(w) is not int or type(fold) is not int or fold not in (0, 1):
                raise ValueError()
            if abs(w) > 10**13:
                raise ValueError()
            results.append(resolve(w, fold))
        elif name == "wall":
            if len(op) != 2: raise ValueError()
            x = op[1]
            if type(x) is not int:
                raise ValueError()
            if abs(x) > 10**13:
                raise ValueError()
            results.append(wall(x))
        elif name == "add":
            if len(op) != 5: raise ValueError()
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if type(w) is not int or type(fold) is not int or fold not in (0, 1):
                raise ValueError()
            if type(days) is not int or type(secs) is not int:
                raise ValueError()
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError()
            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(wall(x2))
        else:
            raise ValueError("unknown operation")
    return results

import bisect

def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone structure")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial type")
    if abs(initial) > 50400:
        raise ValueError("initial range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions type")
    n = len(transitions)
    if n > 100000:
        raise ValueError("transitions count")

    prev_t = None
    prev_off = initial
    ts = []
    offs = []
    L = []

    for i, tr in enumerate(transitions):
        if not isinstance(tr, (list, tuple)) or len(tr) != 2:
            raise ValueError("transition structure")
        t, off = tr
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("t type")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("off type")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("t/off range")
        if prev_t is not None:
            if t <= prev_t or t - prev_t < 172800:
                raise ValueError("t ordering/gap")
        if abs(off - prev_off) > 86400:
            raise ValueError("offset change limit")
        prev_t = t
        prev_off = off
        ts.append(t)
        offs.append(off)
        L.append(t + off)

    # Precompute for fast lookup
    # L is strictly increasing. ts and offs are aligned.
    # We'll use bisect on L.

    # Helper to get offset at instant x
    def get_offset(x):
        idx = bisect.bisect_right(ts, x)
        return offs[idx-1] if idx > 0 else initial

    # Resolve w with fold
    def resolve(w, fold):
        # Find zone index
        if L and w >= L[-1]:
            idx = len(L) - 1
        else:
            idx = bisect.bisect_right(L, w) - 1

        off = offs[idx] if idx >= 0 else initial
        t_curr = ts[idx] if idx >= 0 else None
        t_next = ts[idx+1] if idx+1 < n else None

        # Upper bound for this zone's w range
        upper = (t_next + off) if t_next is not None else float('inf')

        if w >= upper:
            # Gap
            # a is current off, b is next off (or prev off for overlap? No, gap means off increased)
            # Actually, gap occurs when w >= upper. The transition causing it is at t_next (if idx+1 < n)
            # or at t_curr if idx == -1.
            if idx == -1:
                a, b = initial, offs[0]
            else:
                a, b = offs[idx], offs[idx+1]
            return (w - a) if fold == 0 else (w - b)

        # Valid instant in this zone
        x = w - off

        # Check for second match (overlap)
        # Overlap happens if offset decreased at the start of this zone
        if idx > 0:
            prev_off = offs[idx-1]
            if off < prev_off and w < t_curr + prev_off:
                # Two matches: x2 = w - prev_off (earlier), x1 = w - off (later)
                return (w - prev_off) if fold == 0 else x
        elif idx == 0:
            if off < initial and w < t_curr + initial:
                return (w - initial) if fold == 0 else x

        return x

    # Process ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops type")

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op structure")
        if not isinstance(op[0], str):
            raise ValueError("op name type")

        name = op[0]
        if name == "instant":
            if len(op) != 3: raise ValueError("instant args")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool): raise ValueError("w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1): raise ValueError("fold")
            if abs(w) > 10**13: raise ValueError("w range")
            results.append(resolve(w, fold))

        elif name == "wall":
            if len(op) != 2: raise ValueError("wall args")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool): raise ValueError("x")
            if abs(x) > 10**13: raise ValueError("x range")
            off = get_offset(x)
            w = x + off
            # Determine fold: 1 if x is the later of two matching w, else 0
            # x is later if it falls in an overlap region where offset decreased
            idx = bisect.bisect_right(ts, x)
            f = 0
            if idx > 0:
                prev_off = offs[idx-1]
                curr_off = offs[idx-1] # wait, idx points to first t > x. So zone is idx-1.
                # Let's recompute zone index for x
                z_idx = idx - 1
                if z_idx >= 0:
                    curr_off = offs[z_idx]
                    if curr_off < offs[z_idx-1] and x < ts[z_idx] + offs[z_idx-1]:
                        f = 1
                else:
                    if curr_off < initial and x < ts[0] + initial:
                        f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5: raise ValueError("add args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool): raise ValueError("w")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1): raise ValueError("fold")
            if not isinstance(days, int) or isinstance(days, bool): raise ValueError("days")
            if not isinstance(secs, int) or isinstance(secs, bool): raise ValueError("secs")
            if abs(w) > 10**13 or abs(days) > 10**6 or abs(secs) > 10**13: raise ValueError("ranges")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            off = get_offset(x2)
            w_out = x2 + off
            idx = bisect.bisect_right(ts, x2)
            z_idx = idx - 1
            f = 0
            if z_idx >= 0:
                curr_off = offs[z_idx]
                if z_idx > 0 and curr_off < offs[z_idx-1] and x2 < ts[z_idx] + offs[z_idx-1]:
                    f = 1
                elif z_idx == 0 and curr_off < initial and x2 < ts[0] + initial:
                    f = 1
            results.append((w_out, f))

        else:
            raise ValueError("unknown operation")

    return results

