    if type(initial) is not int:
        raise ValueError("Invalid initial type")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Invalid transitions type")

    N = len(transitions)
    T = [None] * N
    OFF = [None] * N

    prev_t = None
    prev_off = initial

    for i, item in enumerate(transitions):
        if not (isinstance(item, (list, tuple)) and len(item) == 2):
            raise ValueError("Invalid transition item")
        t, off = item
        if type(t) is not int or type(off) is not int:
            raise ValueError("Invalid transition types")
        if abs(off) > 50400:
            raise ValueError("Offset out of range")
        if abs(t) > 10**13:
            raise ValueError("Transition time out of range")
        if prev_t is not None:
            if t - prev_t < 172800:
                raise ValueError("Transition times too close")
            if abs(off - prev_off) > 86400:
                raise ValueError("Offset change too large")
        T[i] = t
        OFF[i] = off
        prev_t = t
        prev_off = off

    # Precompute L and R arrays for binary search
    INF = 10**18
    L = [T[i] + OFF[i] for i in range(N)]
    R = [T[i+1] + OFF[i] for i in range(N-1)] + [INF]

    # Cache for operations
    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Invalid op structure")
        if len(op) < 1 or not isinstance(op[0], str):
            raise ValueError("Invalid op name")

        name = op[0]

        if name == "instant":
            if len(op) != 3:
                raise ValueError("Wrong number of items for instant")
            w, fold = op[1], op[2]
            if type(w) is not int or type(fold) is not int:
                raise ValueError("Invalid types for instant")
            if fold not in (0, 1) or type(fold) is bool:
                raise ValueError("Fold must be exactly 0 or 1")
            if abs(w) > 10**13:
                raise ValueError("w out of range")

            # Resolve w
            matches = []
            if w < T[0] + initial:
                matches.append(w - initial)
            else:
                idx = bisect.bisect_right(L, w) - 1
                if idx >= 0:
                    if w < R[idx]:
                        matches.append(w - OFF[idx])
                    if idx + 1 < N and w >= L[idx+1]:
                        matches.append(w - OFF[idx+1])

            if len(matches) == 0:
                # Gap case
                # Find gap transition
                if w < T[0] + initial:
                    # Gap before first transition? Not possible per constraints, but handle safely
                    # Actually gap can only occur between transitions
                    # If w < T[0] + initial, it's in first region, so matches > 0 unless initial changes? 
                    # But initial is fixed. So this branch won't be taken for 0 matches.
                    raise ValueError("Logic error")
                else:
                    idx = bisect.bisect_right(L, w) - 1
                    a = OFF[idx]
                    b = OFF[idx+1]
                    if fold == 0:
                        results.append(w - a)
                    else:
                        results.append(w - b)
            elif len(matches) == 1:
                results.append(matches[0])
            else:
                # Two matches, sorted ascending
                if fold == 0:
                    results.append(matches[0])
                else:
                    results.append(matches[1])

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("Wrong number of items for wall")
            x = op[1]
            if type(x) is not int:
                raise ValueError("Invalid type for wall")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            # Find offset at x
            idx = bisect.bisect_right(T, x) - 1
            if idx < 0:
                off = initial
            else:
                off = OFF[idx]
            w = x + off

            # Determine fold flag
            f = 0
            if idx >= 0:
                prev_off = OFF[idx-1] if idx > 0 else initial
                if prev_off > off and x < T[idx] + prev_off - off:
                    f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("Wrong number of items for add")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if type(w) is not int or type(fold) is not int or type(days) is not int or type(secs) is not int:
                raise ValueError("Invalid types for add")
            if fold not in (0, 1) or type(fold) is bool:
                raise ValueError("Fold must be exactly 0 or 1")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("Values out of range")

            w2 = w + 86400 * days
            # Resolve w2
            matches = []
            if w2 < T[0] + initial:
                matches.append(w2 - initial)
            else:
                idx = bisect.bisect_right(L, w2) - 1
                if idx >= 0:
                    if w2 < R[idx]:
                        matches.append(w2 - OFF[idx])
                    if idx + 1 < N and w2 >= L[idx+1]:
                        matches.append(w2 - OFF[idx+1])

            if len(matches) == 0:
                idx = bisect.bisect_right(L, w2) - 1
                a = OFF[idx]
                b = OFF[idx+1]
                if fold == 0:
                    x1 = w2 - a
                else:
                    x1 = w2 - b
            elif len(matches) == 1:
                x1 = matches[0]
            else:
                x1 = matches[0] if fold == 0 else matches[1]

            x2 = x1 + secs
            # Compute wall(x2)
            idx2 = bisect.bisect_right(T, x2) - 1
            if idx2 < 0:
                off2 = initial
            else:
                off2 = OFF[idx2]
            w2_res = x2 + off2
            f2 = 0
            if idx2 >= 0:
                prev_off2 = OFF[idx2-1] if idx2 > 0 else initial
                if prev_off2 > off2 and x2 < T[idx2] + prev_off2 - off2:
                    f2 = 1
            results.append((w2_res, f2))

        else:
            raise ValueError("Unknown operation")

    return results

