def petri_starts(places, transitions, until, limit):
    # --- Validation ---

    # 1. Validate places
    if not isinstance(places, dict):
        raise ValueError("places must be a dict")
    for p, count in places.items():
        if not isinstance(p, str) or p == "":
            raise ValueError("Place name must be a non-empty string")
        if isinstance(count, bool) or not isinstance(count, int):
            raise ValueError("Token count must be an integer")
        if count < 0 or count > 10**6:
            raise ValueError("Token count out of range")

    # 2. Validate transitions
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list or tuple")
    if len(transitions) > 50:
        raise ValueError("Too many transitions")

    seen_names = set()
    trans_objects = []

    for t_tuple in transitions:
        if not isinstance(t_tuple, tuple) or len(t_tuple) != 6:
            raise ValueError("Each transition must be a tuple of 6 elements")

        name, inputs, outputs, duration, priority, servers = t_tuple

        # Name
        if not isinstance(name, str) or name == "":
            raise ValueError("Transition name must be a non-empty string")
        if name in seen_names:
            raise ValueError("Duplicate transition name")
        seen_names.add(name)

        # Inputs
        if not isinstance(inputs, dict):
            raise ValueError("Inputs must be a dict")
        if len(inputs) == 0:
            raise ValueError("Inputs must not be empty")
        for p, w in inputs.items():
            if p not in places:
                raise ValueError(f"Place '{p}' not found in places")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("Input weight must be an integer")
            if w < 1 or w > 1000:
                raise ValueError("Input weight out of range")

        # Outputs
        if not isinstance(outputs, dict):
            raise ValueError("Outputs must be a dict")
        for p, w in outputs.items():
            if p not in places:
                raise ValueError(f"Place '{p}' not found in places")
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("Output weight must be an integer")
            if w < 1 or w > 1000:
                raise ValueError("Output weight out of range")

        # Duration
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise ValueError("Duration must be an integer")
        if duration < 0 or duration > 10**12:
            raise ValueError("Duration out of range")

        # Priority
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise ValueError("Priority must be an integer")

        # Servers
        if isinstance(servers, bool) or not isinstance(servers, int):
            raise ValueError("Servers must be an integer")
        if servers < 1 or servers > 10**6:
            raise ValueError("Servers out of range")

        trans_objects.append({
            'name': name,
            'inputs': inputs,
            'outputs': outputs,
            'duration': duration,
            'priority': priority,
            'servers': servers
        })

    # 3. Validate until
    if isinstance(until, bool) or not isinstance(until, int):
        raise ValueError("until must be an integer")
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    # 4. Validate limit
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an integer")
    if limit < 1 or limit > 2000:
        raise ValueError("limit out of range")

    # --- Simulation ---

    tokens = dict(places)
    # Active firings: list of dicts { 'trans_idx': int, 'completion_time': int }
    active_firings = []
    # Count of active firings per transition
    active_counts = [0] * len(trans_objects)

    starts_recorded = []
    current_time = 0

    while len(starts_recorded) < limit and current_time <= until:
        # 1. Process completions at current_time
        # Identify all firings completing exactly at current_time
        completions = [f for f in active_firings if f['completion_time'] == current_time]

        for f in completions:
            idx = f['trans_idx']
            active_counts[idx] -= 1
            # Add outputs
            trans = trans_objects[idx]
            for p, w in trans['outputs'].items():
                tokens[p] += w

        # Remove completed firings
        active_firings = [f for f in active_firings if f['completion_time'] != current_time]

        # 2. Try to start transitions repeatedly
        while True:
            # Find enabled transitions
            enabled = []
            for idx, trans in enumerate(trans_objects):
                # Check servers
                if active_counts[idx] >= trans['servers']:
                    continue

                # Check inputs
                inputs_ok = True
                for p, w in trans['inputs'].items():
                    if tokens.get(p, 0) < w:
                        inputs_ok = False
                        break

                if inputs_ok:
                    enabled.append((trans['priority'], idx, trans))

            if not enabled:
                break

            # Sort by priority (asc), then index (asc)
            enabled.sort(key=lambda x: (x[0], x[1]))

            best = enabled[0]
            trans = best[2]
            idx = best[1]
            name = trans['name']

            # Start firing
            # Deduct inputs
            for p, w in trans['inputs'].items():
                tokens[p] -= w

            # Record start
            starts_recorded.append((current_time, name))

            # Check limit immediately
            if len(starts_recorded) == limit:
                return starts_recorded

            # Handle duration
            if trans['duration'] > 0:
                active_counts[idx] += 1
                active_firings.append({
                    'trans_idx': idx,
                    'completion_time': current_time + trans['duration']
                })
            else:
                # Duration 0: outputs put in immediately
                for p, w in trans['outputs'].items():
                    tokens[p] += w
                # Never counts as in progress, so active_counts remains unchanged

        # 3. Advance time
        if not active_firings:
            # No firings in progress. Simulation ends.
            break

        # Find next completion time
        next_time = min(f['completion_time'] for f in active_firings)

        if next_time > until:
            break

        current_time = next_time

    return starts_recorded

