    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gate_outs = set()
    all_signals = set()
    gate_objects = []

    # Parse gates
    for g in gates:
        if not isinstance(g, (list, tuple)) or len(g) != 4:
            raise ValueError("Each gate must be a tuple of 4 elements")
        out, op, ins, delay = g

        if not isinstance(out, str) or not out:
            raise ValueError("Gate output must be a non-empty string")
        if out in gate_outs:
            raise ValueError("Duplicate gate output")
        gate_outs.add(out)

        if op not in valid_ops:
            raise ValueError("Invalid gate operation")

        if not isinstance(ins, (list, tuple)) or len(ins) == 0:
            raise ValueError("Gate inputs must be a non-empty list/tuple")
        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("Gate input names must be non-empty strings")

        if not isinstance(delay, int) or isinstance(delay, bool):
            raise ValueError("Gate delay must be an int")
        if delay < 0 or delay > 10**12:
            raise ValueError("Gate delay out of range")

        # Check input arity
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError("NOT/BUF requires 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError("AND/OR/XOR/NAND/NOR requires 2-4 inputs")

        gate_objects.append((out, op, list(ins), delay))
        all_signals.add(out)
        for i in ins:
            all_signals.add(i)

    # Identify Primary Inputs
    primary_inputs = all_signals - gate_outs

    # Parse stimuli
    parsed_stimuli = []
    for s in stimuli:
        if not isinstance(s, (list, tuple)) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple of 3 elements")
        time, signal, value = s

        if not isinstance(time, int) or isinstance(time, bool):
            raise ValueError("Stimulus time must be an int")
        if time < 0 or time > 10**12:
            raise ValueError("Stimulus time out of range")

        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be a non-empty string")
        if signal not in primary_inputs:
            raise ValueError("Stimulus signal is not a primary input (unknown or driven)")

        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("Stimulus value must be an int")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

        parsed_stimuli.append((time, signal, value))

    # Parse watch
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch signal must be a non-empty string")
        if w not in all_signals:
            raise ValueError("Watch signal is unknown")

    # Cycle Detection
    # Build graph: input -> out
    adj = {s: [] for s in all_signals}
    for out, op, ins, delay in gate_objects:
        for i in ins:
            adj[i].append(out)

    # DFS for cycle
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {s: WHITE for s in all_signals}

    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE:
                if has_cycle(v):
                    return True
        color[u] = BLACK
        return False

    for s in all_signals:
        if color[s] == WHITE:
            if has_cycle(s):
                raise ValueError("Cycle detected in gate graph")

    # --- Simulation Setup ---

    # Gate lookup
    gate_map = {}
    for out, op, ins, delay in gate_objects:
        gate_map[out] = (op, ins, delay)

    # Dependents: signal -> list of gate outputs that use it
    dependents = {s: [] for s in all_signals}
    for out, op, ins, delay in gate_objects:
        for i in ins:
            dependents[i].append(out)

    # State
    values = {s: 0 for s in all_signals}
    # Pending assignments: out -> (due_time, value)
    pending = {} 
    # Heap for pending assignments: (due_time, out)
    import heapq
    pending_heap = []

    # Stimuli processing
    parsed_stimuli.sort(key=lambda x: x[0])
    stimuli_idx = 0
    num_stimuli = len(parsed_stimuli)

    # Trace
    last_values = {w: 0 for w in watch}
    trace = {w: [] for w in watch}

    # Helper to apply pending assignments due at time t
    # Returns set of signals that changed
    def apply_pending(t):
        changed = set()
        # We need to collect all valid pending assignments due at t
        # Since we might have stale entries in heap, we check pending dict
        # But iterating dict is safer for correctness of "all due at t"
        # However, we need to remove them from heap or mark them?
        # Actually, if we remove from dict, they are gone.
        # But heap might still have them. We handle heap lazily.

        # Find assignments due at t
        to_apply = []
        for out, (due, val) in list(pending.items()):
            if due == t:
                to_apply.append((out, val))

        # Apply
        for out, val in to_apply:
            if values[out] != val:
                values[out] = val
                changed.add(out)
            # Remove from pending
            del pending[out]

        return changed

    # Helper to evaluate gates
    # Returns set of signals that changed (outputs)
    def evaluate_gates(changed_inputs):
        new_changes = set()
        # Find gates to evaluate
        gates_to_eval = set()
        for sig in changed_inputs:
            for out in dependents[sig]:
                gates_to_eval.add(out)

        # Also if t=0, evaluate all gates? 
        # Prompt: "in the first round of instant 0: every gate"
        # This is handled by calling evaluate_gates with all signals changed at t=0 round 0.

        for out in gates_to_eval:
            # Delete own pending assignment
            if out in pending:
                del pending[out]

            # Compute
            op, ins, delay = gate_map[out]
            in_vals = [values[i] for i in ins]

            if op == "AND":
                new_val = 1 if all(in_vals) else 0
            elif op == "OR":
                new_val = 1 if any(in_vals) else 0
            elif op == "XOR":
                new_val = sum(in_vals) % 2
            elif op == "NAND":
                new_val = 0 if all(in_vals) else 1
            elif op == "NOR":
                new_val = 1 if not any(in_vals) else 0
            elif op == "NOT":
                new_val = 1 - in_vals[0]
            elif op == "BUF":
                new_val = in_vals[0]
            else:
                new_val = 0 # Should not happen

            if new_val != values[out]:
                due = t + delay
                pending[out] = (due, new_val)
                heapq.heappush(pending_heap, (due, out))
                new_changes.add(out)

        return new_changes

    # Main Loop
    # Collect initial event times
    # We process instants.

    # Helper to get next event time
    def get_next_time():
        t_next = float('inf')
        # From stimuli
        if stimuli_idx < num_stimuli:
            t_next = min(t_next, parsed_stimuli[stimuli_idx][0])
        # From pending
        if pending_heap:
            t_next = min(t_next, pending_heap[0][0])
        return t_next

    # Start at time 0 if there are events or if we need to process initial state?
    # "Simulated instants... 0, every stimulus time, and every time at which an assignment is due"
    # If no events at 0, do we process 0?
    # "The trace... differs from the final value at the previous simulated instant (0 before instant 0)."
    # If nothing happens at 0, value is 0. Trace records if value changes from 0.
    # Since init is 0, no change.
    # But we might have stimuli at 0.

    # We need to process instant 0 if there are stimuli or pending assignments due at 0.
    # Or just generally loop while next_time <= until.

    # Initial check: do we have events at 0?
    # If not, and until >= 0, we might still need to check if we should start?
    # Actually, if no events, simulation ends.

    # But wait, if until >= 0, and we have no events, we stop.
    # The trace logic: "differs from ... previous simulated instant".
    # Before instant 0, value is 0.
    # If instant 0 happens and value changes, record.
    # If instant 0 doesn't happen (no events), we don't record anything new.

    # However, we must ensure we process 0 if there are stimuli at 0.

    # Let's just loop.

    while True:
        t = get_next_time()
        if t > until:
            break
        if t == float('inf'):
            break

        # --- Instant t ---

        # Round 0
        # 1. Apply stimuli
        while stimuli_idx < num_stimuli and parsed_stimuli[stimuli_idx][0] == t:
            _, sig, val = parsed_stimuli[stimuli_idx]
            values[sig] = val
            stimuli_idx += 1

        # 2. Apply pending assignments due at t
        changed = apply_pending(t)

        # 3. Evaluate
        # If t=0, evaluate all gates. Else, gates with changed inputs.
        if t == 0:
            # Force evaluation of all gates by marking all signals changed?
            # Or just pass a set of all signals?
            # "in the first round of instant 0: every gate"
            # So we can just call evaluate_gates with all_signals
            changed = evaluate_gates(all_signals)
        else:
            changed = evaluate_gates(changed)

        # Check for more work in this instant (delay 0 assignments)
        # We need to continue rounds while some assignment is due at t.
        # Since we just processed assignments due at t, we need to check if new ones were added with due=t.
        # These would be in pending dict with due=t.

        while any(due == t for due, _ in pending.values()):
            # Round 1+
            # Apply pending assignments due at t
            changed = apply_pending(t)
            # Evaluate
            changed = evaluate_gates(changed)

        # End of Instant t
        # Record trace
        for w in watch:
            v = values[w]
            if v != last_values[w]:
                trace[w].append((t, v))
                last_values[w] = v

    return trace

