import heapq
from collections import defaultdict, deque

def gate_trace(gates, stimuli, watch, until):
    # --- Validation ---
    if not isinstance(until, int) or isinstance(until, bool):
        raise ValueError("until must be an int")
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")
    if not (0 <= len(gates) <= 60):
        raise ValueError("gates length out of range")

    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    if not (0 <= len(stimuli) <= 200):
        raise ValueError("stimuli length out of range")

    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gate_map = {}
    out_signals = set()
    all_signals = set()
    gate_list = []

    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple of 4 elements")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("Gate output name must be a non-empty string")
        if out in out_signals:
            raise ValueError("Duplicate gate output names")
        out_signals.add(out)
        if op not in valid_ops:
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} requires 2 to 4 inputs")
        for name in ins:
            if not isinstance(name, str) or not name:
                raise ValueError("Input names must be non-empty strings")
            all_signals.add(name)
        if not isinstance(delay, int) or isinstance(delay, bool):
            raise ValueError("Delay must be an int")
        if delay < 0 or delay > 10**12:
            raise ValueError("Delay out of range")
        all_signals.add(out)
        gate_map[out] = {"op": op, "ins": list(ins), "delay": delay}
        gate_list.append(out)

    primary_inputs = all_signals - out_signals

    stimuli_events = []
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Stimulus must be a tuple of (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool):
            raise ValueError("Stimulus time must be an int")
        if time < 0 or time > 10**12:
            raise ValueError("Stimulus time out of range")
        if signal not in all_signals:
            raise ValueError(f"Unknown stimulus signal: {signal}")
        if signal in out_signals:
            raise ValueError(f"Stimulus signal '{signal}' is driven by a gate")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")
        stimuli_events.append((time, signal, value))

    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Unknown watch name: {w}")

    # Cycle detection
    adj = defaultdict(list)
    in_degree = {s: 0 for s in all_signals}
    for out_name, info in gate_map.items():
        for inp in info["ins"]:
            adj[inp].append(out_name)
            in_degree[out_name] += 1

    queue = [n for n in all_signals if in_degree[n] == 0]
    visited = 0
    while queue:
        u = queue.pop(0)
        visited += 1
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if visited != len(all_signals):
        raise ValueError("Cycle detected in gate graph")

    # Fanout map
    fanout = defaultdict(list)
    for out_name, info in gate_map.items():
        for inp in info["ins"]:
            fanout[inp].append(out_name)

    def eval_gate(op, inputs_vals):
        if op == "AND":
            v = 1
            for x in inputs_vals: v &= x
            return v
        elif op == "OR":
            v = 0
            for x in inputs_vals: v |= x
            return v
        elif op == "XOR":
            v = 0
            for x in inputs_vals: v ^= x
            return v
        elif op == "NAND":
            v = 1
            for x in inputs_vals: v &= x
            return 1 - v
        elif op == "NOR":
            v = 0
            for x in inputs_vals: v |= x
            return 1 - v
        elif op == "NOT":
            return 1 - inputs_vals[0]
        elif op == "BUF":
            return inputs_vals[0]
        return 0

    # --- Simulation ---
    values = {s: 0 for s in all_signals}
    prev_values = {s: 0 for s in all_signals}
    pending_heap = []
    pending_map = {}
    immediate_queue = deque()
    trace = {w: [] for w in watch}

    stimuli_events.sort(key=lambda x: x[0])
    stim_idx = 0
    num_stimuli = len(stimuli_events)
    current_time = 0

    while current_time <= until:
        changed_signals = set()

        # Round 1 Batch
        while stim_idx < num_stimuli and stimuli_events[stim_idx][0] == current_time:
            _, sig, val = stimuli_events[stim_idx]
            stim_idx += 1
            if values[sig] != val:
                changed_signals.add(sig)
            values[sig] = val

        while pending_heap and pending_heap[0][0] == current_time:
            t, out, val = heapq.heappop(pending_heap)
            if out in pending_map and pending_map[out] == (t, val):
                if values[out] != val:
                    changed_signals.add(out)
                values[out] = val
                del pending_map[out]

        # Evaluation Round 1
        if current_time == 0:
            gates_to_eval = set(gate_map.keys())
        else:
            gates_to_eval = set()
            for s in changed_signals:
                if s in fanout:
                    gates_to_eval.update(fanout[s])

        for out_name in gates_to_eval:
            gate_info = gate_map[out_name]
            if out_name in pending_map:
                del pending_map[out_name]

            input_vals = [values[inp] for inp in gate_info["ins"]]
            new_val = eval_gate(gate_info["op"], input_vals)

            if new_val != values[out_name]:
                delay = gate_info["delay"]
                due_time = current_time + delay
                if delay == 0:
                    immediate_queue.append((out_name, new_val))
                else:
                    heapq.heappush(pending_heap, (due_time, out_name, new_val))
                    pending_map[out_name] = (due_time, new_val)

        # Delta Rounds
        while immediate_queue:
            changed_signals = set()
            while immediate_queue:
                out, val = immediate_queue.popleft()
                if values[out] != val:
                    changed_signals.add(out)
                values[out] = val

            gates_to_eval = set()
            for s in changed_signals:
                if s in fanout:
                    gates_to_eval.update(fanout[s])

            for out_name in gates_to_eval:
                gate_info = gate_map[out_name]
                if out_name in pending_map:
                    del pending_map[out_name]

                input_vals = [values[inp] for inp in gate_info["ins"]]
                new_val = eval_gate(gate_info["op"], input_vals)

                if new_val != values[out_name]:
                    delay = gate_info["delay"]
                    due_time = current_time + delay
                    if delay == 0:
                        immediate_queue.append((out_name, new_val))
                    else:
                        heapq.heappush(pending_heap, (due_time, out_name, new_val))
                        pending_map[out_name] = (due_time, new_val)

        # Record trace
        for w in watch:
            if values[w] != prev_values[w]:
