        for w in trace:
            if values[w] != prev_values[w]:
                trace[w].append((current_time, values[w]))

        prev_values = {s: values[s] for s in all_signals}

        # --- Find Next Time ---
        next_t = None

        # Next stimulus time
        # We need to find the smallest time in stim_dict keys that is > current_time
        # But iterating keys might be slow if many keys? 
        # Actually number of stimuli <= 200, so it's fine.
        # Or we can just track an index if we sorted, but we didn't.
