import heapq

def gate_trace(gates, stimuli, watch, until):
    # Validation helpers
    def check_int(val):
        if type(val) is not int or isinstance(val, bool):
            raise ValueError("Not an int")

    # Validate gates
    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    outs = set()
    known_signals = set()
    gates_parsed = []

    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be list/tuple")
    if len(gates) > 60:
        raise ValueError("Too many gates")

    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Gate tuple must have 4 elements")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("out must be non-empty str")
        if out in outs:
            raise ValueError("Duplicate out")
        outs.add(out)
        if op not in valid_ops:
            raise ValueError("Invalid op")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("ins must be list/tuple")
        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("ins elements must be non-empty str")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError("NOT/BUF must have 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError("AND/OR/etc must have 2-4 inputs")
        check_int(delay)
        if delay < 0 or delay > 10**12:
            raise ValueError("delay out of range")

        gates_parsed.append({"out": out, "op": op, "ins": list(ins), "delay": delay})
        known_signals.add(out)
        known_signals.update(ins)

    # Validate stimuli
    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be list/tuple")
    if len(stimuli) > 200:
        raise ValueError("Too many stimuli")

    stimuli_by_time = {}
    for st in stimuli:
        if not isinstance(st, tuple) or len(st) != 3:
            raise ValueError("Stimulus tuple must have 3 elements")
        t, sig, val = st
        check_int(t)
        if t < 0 or t > 10**12:
            raise ValueError("stimulus time out of range")
        if not isinstance(sig, str) or not sig:
            raise ValueError("signal must be non-empty str")
        if val not in (0, 1):
            raise ValueError("value must be 0 or 1")
        if sig not in known_signals:
            raise ValueError("Unknown stimulus signal")
        if sig in outs:
            raise ValueError("Stimulus signal is driven by a gate")
        stimuli_by_time.setdefault(t, []).append((sig, val))

    # Validate watch
    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be list/tuple")
    watch_set = set(watch)
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("watch elements must be non-empty str")
        if w not in known_signals:
            raise ValueError("Unknown watch signal")

    check_int(until)
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    # Cycle detection
    graph = {sig: [] for sig in known_signals}
    for g in gates_parsed:
        for inp in g["ins"]:
            graph[inp].append(g["out"])

    visited = set()
    rec_stack = set()
    def has_cycle(u):
        visited.add(u)
        rec_stack.add(u)
        for v in graph[u]:
            if v not in visited:
                if has_cycle(v):
                    return True
            elif v in rec_stack:
                return True
        rec_stack.remove(u)
        return False

    for sig in known_signals:
        if sig not in visited:
            if has_cycle(sig):
                raise ValueError("Cycle detected")

    # Simulation
    current_values = {sig: 0 for sig in known_signals}
    pending = {} # {signal: (value, due_time)}
    times_heap = [0]
    for t in stimuli_by_time:
        times_heap.append(t)
    heapq.heapify(times_heap)

    trace = {name: [] for name in watch}
    prev_values = {sig: 0 for sig in watch}
    processed_times = set()
    all_gates = gates_parsed

    while times_heap:
        t = heapq.heappop(times_heap)
        if t > until:
            break
        if t in processed_times:
            continue
        processed_times.add(t)

        changes = set()
        round_num = 0

        while True:
            # Batch phase
            if round_num == 0:
                if t in stimuli_by_time:
                    for sig, val in stimuli_by_time[t]:
                        if current_values[sig] != val:
                            current_values[sig] = val
                            changes.add(sig)
                due_now = [sig for sig, (val, due) in pending.items() if due == t]
                for sig in due_now:
                    val, _ = pending.pop(sig)
                    if current_values[sig] != val:
                        current_values[sig] = val
                        changes.add(sig)
            else:
                due_now = [sig for sig, (val, due) in pending.items() if due == t]
                for sig in due_now:
                    val, _ = pending.pop(sig)
                    if current_values[sig] != val:
                        current_values[sig] = val
                        changes.add(sig)

            # Evaluate phase
            new_pending = dict(pending)
            gates_to_eval = []
            if round_num == 0 and t == 0:
                gates_to_eval = all_gates
            else:
                for g in all_gates:
                    if any(inp in changes for inp in g["ins"]):
                        gates_to_eval.append(g)

            for g in gates_to_eval:
                if g["out"] in new_pending:
                    del new_pending[g["out"]]

                vals = [current_values[inp] for inp in g["ins"]]
                op = g["op"]
                if op == "AND":
                    new_val = 1 if all(vals) else 0
                elif op == "OR":
                    new_val = 1 if any(vals) else 0
                elif op == "XOR":
                    new_val = 1 if sum(vals) % 2 else 0
                elif op == "NAND":
                    new_val = 0 if all(vals) else 1
                elif op == "NOR":
                    new_val = 1 if not any(vals) else 0
                elif op == "NOT":
                    new_val = 1 - vals[0]
                elif op == "BUF":
                    new_val = vals[0]

                if new_val != current_values[g["out"]]:
                    due_time = t + g["delay"]
                    new_pending[g["out"]] = (new_val, due_time)
                    if due_time <= until:
