def gate_trace(gates, stimuli, watch, until):
    # --- Validation and Parsing ---

    # Check types for gates
    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")
    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple (out, op, ins, delay)")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("Gate out must be a non-empty string")
        if op not in ("AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"):
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Gate inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} gate requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} gate requires 2 to 4 inputs")
        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12:
            raise ValueError("Gate delay must be an integer 0..10**12")

    # Check types for stimuli
    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool) or time < 0 or time > 10**12:
            raise ValueError("Stimulus time must be an integer 0..10**12")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be a non-empty string")
        if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

    # Check types for watch
    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch names must be non-empty strings")

    # Check types for until
    if not isinstance(until, int) or isinstance(until, bool) or until < 0 or until > 10**12:
        raise ValueError("until must be an integer 0..10**12")

    # Collect all signals from gates
    all_signals = set()
    gate_map = {}  # out -> {op, ins, delay}
    out_names = set()

    # Graph for cycle detection: input -> [outputs]
    graph = {} 

    for out, op, ins, delay in gates:
        out_names.add(out)
        all_signals.add(out)
        gate_map[out] = {'op': op, 'ins': list(ins), 'delay': delay}

        if out not in graph:
            graph[out] = []

        for inp in ins:
            all_signals.add(inp)
            if inp not in graph:
                graph[inp] = []
            graph[inp].append(out)

    # Check for cycles using DFS
    # 0: unvisited, 1: visiting, 2: visited
    color = {s: 0 for s in all_signals}
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        if has_cycle: return
        color[u] = 1
        for v in graph.get(u, []):
            if color[v] == 1:
                has_cycle = True
                return
            if color[v] == 0:
                dfs(v)
        color[u] = 2

    for s in all_signals:
        if color[s] == 0:
            dfs(s)
            if has_cycle:
                raise ValueError("Cycle detected in gate graph")

    # Identify primary inputs
    primary_inputs = all_signals - out_names

    # Validate stimuli signals
    for _, signal, _ in stimuli:
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input")

    # Validate watch names
    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Watch name '{w}' is not a known signal")

    # --- Simulation Setup ---

    # Logic functions
    def evaluate(op, inputs_vals):
        if op == "AND":
            return 1 if all(inputs_vals) else 0
        elif op == "OR":
            return 1 if any(inputs_vals) else 0
        elif op == "XOR":
            return 1 if sum(inputs_vals) % 2 == 1 else 0
        elif op == "NAND":
            return 0 if all(inputs_vals) else 1
        elif op == "NOR":
            return 0 if any(inputs_vals) else 1
        elif op == "NOT":
            return 1 - inputs_vals[0]
        elif op == "BUF":
            return inputs_vals[0]
        return 0

    # Initial state
    signal_values = {s: 0 for s in all_signals}

    # Pending assignments: out_name -> (due_time, value)
    # Only one pending assignment per gate allowed.
    pending = {} 

    # Organize stimuli by time
    stimuli_by_time = {}
    for time, signal, value in stimuli:
        if time not in stimuli_by_time:
            stimuli_by_time[time] = []
        stimuli_by_time[time].append((signal, value))

    # Collect all event times (0 and stimulus times)
    event_times = set([0])
    for time, _, _ in stimuli:
        if time <= until:
            event_times.add(time)
    sorted_times = sorted(list(event_times))

    # Trace storage
    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch}

    # --- Simulation Loop ---

    for t in sorted_times:
        if t > until:
            break

        # --- Rounds at instant t ---

        # We need to process rounds until no assignments are pending for time t.
        # However, we must be careful not to loop infinitely if logic is weird, 
        # though DAG ensures termination.

        # Round 1: Batch
        # Apply stimuli
        if t in stimuli_by_time:
            # Process in list order; later overrides earlier
            for signal, value in stimuli_by_time[t]:
                signal_values[signal] = value

        # Apply pending assignments due at t
        # Note: We collect them first to avoid modification during iteration issues,
        # though dict removal is safe if careful.
        assignments_to_apply = []
        for out_name, (due_time, value) in list(pending.items()):
            if due_time == t:
                assignments_to_apply.append((out_name, value))

        # Apply them
        changed_signals_round1 = set()
        for out_name, value in assignments_to_apply:
            if signal_values[out_name] != value:
                changed_signals_round1.add(out_name)
            signal_values[out_name] = value
            # Remove from pending
            if out_name in pending and pending[out_name][0] == t:
                del pending[out_name]

        # If delay was 0, assignment is due at t. It was applied in Batch.
        # But wait, if a gate scheduled an assignment with delay 0 in a previous round of t,
        # it would be in pending with due_time=t. It gets applied here.

        # Determine signals that changed in Round 1 Batch
        # "A signal 'changed' in the round if its value after the batch differs from before it."
        # Before Round 1 Batch: Initial values of instant t.
        # We tracked changes in `changed_signals_round1`.

        # Evaluate gates
        # "Every gate with an input that changed in this round ... computes"
        # We need to identify gates whose inputs are in `changed_signals_round1`.

        gates_to_eval = []
        for out_name, g_info in gate_map.items():
            inputs_changed = False
            for inp in g_info['ins']:
                if inp in changed_signals_round1:
                    inputs_changed = True
                    break
            if inputs_changed:
                gates_to_eval.append(out_name)

        # Process evaluations
        # "It first deletes its own pending assignment"
        # "then, if the computed value differs from its out's current value, queues ..."

        new_pending_this_round = []

        for out_name in gates_to_eval:
            g_info = gate_map[out_name]
            # Compute current inputs
            input_vals = [signal_values[inp] for inp in g_info['ins']]
            new_val = evaluate(g_info['op'], input_vals)
            curr_val = signal_values[out_name]

            # Delete existing pending assignment for this gate
            if out_name in pending:
                del pending[out_name]

            # If value differs, schedule new pending
            if new_val != curr_val:
                due_time = t + g_info['delay']
                # Store in a list to add back to pending after processing all gates?
                # Prompt: "queues (out := value) due at t + delay"
                # If delay 0, due at t.
                pending[out_name] = (due_time, new_val)
                new_pending_this_round.append((out_name, due_time, new_val))

        # Check if we need another round
        # "Rounds continue while some assignment is due at t."
        # Assignments due at t are those with due_time == t.
        # These could be from `assignments_to_apply` (already applied) or `new_pending_this_round` (delay 0).
        # Since we applied `assignments_to_apply`, we just need to check if there are any pending with due_time == t.

        has_pending_at_t = False
        for out_name, (due_time, val) in pending.items():
            if due_time == t:
                has_pending_at_t = True
                break

        while has_pending_at_t:
            # Next Round (Round 2+)
            # a. Batch
            # "In the later rounds apply the assignments due at t (queued by the previous round with delay 0)."
            # Apply pending assignments due at t
            assignments_to_apply_next = []
            for out_name, (due_time, value) in list(pending.items()):
                if due_time == t:
                    assignments_to_apply_next.append((out_name, value))

            changed_signals_next = set()
            for out_name, value in assignments_to_apply_next:
                if signal_values[out_name] != value:
                    changed_signals_next.add(out_name)
                signal_values[out_name] = value
                if out_name in pending and pending[out_name][0] == t:
                    del pending[out_name]

            # b. Evaluate
            gates_to_eval_next = []
            for out_name, g_info in gate_map.items():
                inputs_changed = False
                for inp in g_info['ins']:
                    if inp in changed_signals_next:
                        inputs_changed = True
                        break
                if inputs_changed:
                    gates_to_eval_next.append(out_name)

            for out_name in gates_to_eval_next:
                g_info = gate_map[out_name]
                input_vals = [signal_values[inp] for inp in g_info['ins']]
                new_val = evaluate(g_info['op'], input_vals)
                curr_val = signal_values[out_name]

                if out_name in pending:
                    del pending[out_name]

                if new_val != curr_val:
                    due_time = t + g_info['delay']
                    pending[out_name] = (due_time, new_val)

            # Check termination
            has_pending_at_t = False
            for out_name, (due_time, val) in pending.items():
                if due_time == t:
                    has_pending_at_t = True
                    break

        # --- End of Instant t ---
        # Record trace
        for w in watch:
            curr_val = signal_values[w]
            prev_val = last_values[w]
            if curr_val != prev_val:
                trace[w].append((t, curr_val))
                last_values[w] = curr_val

    return trace

def gate_trace(gates, stimuli, watch, until):
    # --- Validation and Parsing ---
    if not isinstance(gates, (list, tuple)):
        raise ValueError("gates must be a list or tuple")
    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple (out, op, ins, delay)")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("Gate out must be a non-empty string")
        if op not in ("AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"):
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Gate inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} gate requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} gate requires 2 to 4 inputs")
        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12:
            raise ValueError("Gate delay must be an integer 0..10**12")

    if not isinstance(stimuli, (list, tuple)):
        raise ValueError("stimuli must be a list or tuple")
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool) or time < 0 or time > 10**12:
            raise ValueError("Stimulus time must be an integer 0..10**12")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be a non-empty string")
        if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

    if not isinstance(watch, (list, tuple)):
        raise ValueError("watch must be a list or tuple")
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch names must be non-empty strings")

    if not isinstance(until, int) or isinstance(until, bool) or until < 0 or until > 10**12:
        raise ValueError("until must be an integer 0..10**12")

    all_signals = set()
    gate_map = {}
    out_names = set()
    graph = {}

    for out, op, ins, delay in gates:
        if out in out_names:
            raise ValueError("Duplicate gate output")
        out_names.add(out)
        all_signals.add(out)
        gate_map[out] = {'op': op, 'ins': list(ins), 'delay': delay}

        if out not in graph:
            graph[out] = []

        for inp in ins:
            all_signals.add(inp)
            if inp not in graph:
                graph[inp] = []
            graph[inp].append(out)

    color = {s: 0 for s in all_signals}
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        if has_cycle: return
        color[u] = 1
        for v in graph.get(u, []):
            if color[v] == 1:
                has_cycle = True
                return
            if color[v] == 0:
                dfs(v)
        color[u] = 2

    for s in all_signals:
        if color[s] == 0:
            dfs(s)
            if has_cycle:
                raise ValueError("Cycle detected in gate graph")

    primary_inputs = all_signals - out_names

    for _, signal, _ in stimuli:
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input")

    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Watch name '{w}' is not a known signal")

    def evaluate(op, inputs_vals):
        if op == "AND":
            return 1 if all(inputs_vals) else 0
        elif op == "OR":
            return 1 if any(inputs_vals) else 0
        elif op == "XOR":
            return 1 if sum(inputs_vals) % 2 == 1 else 0
        elif op == "NAND":
            return 0 if all(inputs_vals) else 1
        elif op == "NOR":
            return 0 if any(inputs_vals) else 1
        elif op == "NOT":
            return 1 - inputs_vals[0]
        elif op == "BUF":
            return inputs_vals[0]
        return 0

    signal_values = {s: 0 for s in all_signals}
    pending = {}

    stimuli_by_time = {}
    for time, signal, value in stimuli:
        if time not in stimuli_by_time:
            stimuli_by_time[time] = []
        stimuli_by_time[time].append((signal, value))

    event_times = set([0])
    for time, _, _ in stimuli:
        if time <= until:
            event_times.add(time)
    sorted_times = sorted(list(event_times))

    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch}

    for t in sorted_times:
        if t > until:
            break

        # Round 1 Batch
        changed_signals = set()

        if t in stimuli_by_time:
            for signal, value in stimuli_by_time[t]:
                if signal_values[signal] != value:
                    changed_signals.add(signal)
                signal_values[signal] = value

        assignments_at_t = [(out, val) for out, (due, val) in pending.items() if due == t]
        for out, val in assignments_at_t:
            if signal_values[out] != val:
                changed_signals.add(out)
            signal_values[out] = val
            del pending[out]

        # Evaluate
        gates_to_eval = []
        for out_name, g_info in gate_map.items():
            if any(inp in changed_signals for inp in g_info['ins']):
                gates_to_eval.append(out_name)

        for out_name in gates_to_eval:
            g_info = gate_map[out_name]
            input_vals = [signal_values[inp] for inp in g_info['ins']]
            new_val = evaluate(g_info['op'], input_vals)
            curr_val = signal_values[out_name]

            if out_name in pending:
                del pending[out_name]

            if new_val != curr_val:
                due_time = t + g_info['delay']
                pending[out_name] = (due_time, new_val)

        # Subsequent Rounds
        while any(due == t for due, _ in pending.values()):
            changed_signals = set()
            assignments_at_t = [(out, val) for out, (due, val) in pending.items() if due == t]
            for out, val in assignments_at_t:
                if signal_values[out] != val:
                    changed_signals.add(out)
                signal_values[out] = val
                del pending[out]

            gates_to_eval = []
            for out_name, g_info in gate_map.items():
                if any(inp in changed_signals for inp in g_info['ins']):
                    gates_to_eval.append(out_name)

            for out_name in gates_to_eval:
                g_info = gate_map[out_name]
                input_vals = [signal_values[inp] for inp in g_info['ins']]
                new_val = evaluate(g_info['op'], input_vals)
                curr_val = signal_values[out_name]

                if out_name in pending:
                    del pending[out_name]

                if new_val != curr_val:
                    due_time = t + g_info['delay']
                    pending[out_name] = (due_time, new_val)

        # Record trace
        for w in watch:
            curr_val = signal_values[w]
            prev_val = last_values[w]
            if curr_val != prev_val:
                trace[w].append((t, curr_val))
                last_values[w] = curr_val

    return trace

import sys

sys.setrecursionlimit(10000)

class TVar:
    __slots__ = ('sid',)
    def __init__(self, sid):
        self.sid = sid
    def __repr__(self): return f"TVar({self.sid})"

class Base:
    __slots__ = ('name',)
    def __init__(self, name):
        self.name = name

class List:
    __slots__ = ('elem',)
    def __init__(self, elem):
        self.elem = elem

class Ref:
    __slots__ = ('elem',)
    def __init__(self, elem):
        self.elem = elem

class Func:
    __slots__ = ('args', 'ret')
    def __init__(self, args, ret):
        self.args = args
        self.ret = ret

def follow(t, sub):
    while isinstance(t, TVar) and t in sub:
        t = sub[t]
    return t

def bind(x, y, sub):
    y = follow(y, sub)
    if isinstance(y, TVar) and y.sid == x.sid:
        return
    # Occurs check
    def occurs(v, t):
        t = follow(t, sub)
        if isinstance(t, TVar):
            return t.sid == v.sid
        if isinstance(t, List): return occurs(v, t.elem)
        if isinstance(t, Ref): return occurs(v, t.elem)
        if isinstance(t, Func):
            return any(occurs(v, a) for a in t.args) or occurs(v, t.ret)
        return False
    if occurs(x, y):
        raise ValueError("Infinite type")
    sub[x] = y

def unify(t1, t2, sub):
    t1 = follow(t1, sub)
    t2 = follow(t2, sub)
    if t1 is t2: return
    if isinstance(t1, TVar):
        bind(t1, t2, sub)
    elif isinstance(t2, TVar):
        bind(t2, t1, sub)
    elif isinstance(t1, Base) and isinstance(t2, Base):
        if t1.name != t2.name: raise ValueError("Type mismatch")
    elif isinstance(t1, List) and isinstance(t2, List):
        unify(t1.elem, t2.elem, sub)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        unify(t1.elem, t2.elem, sub)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            unify(a1, a2, sub)
        unify(t1.ret, t2.ret, sub)
    else:
        raise ValueError("Type mismatch")

def free_vars(t, fvs=None):
    if fvs is None: fvs = set()
    t = follow(t, {}) # follow in empty sub to get raw structure, but we need current sub? 
    # Actually, we should follow with the current sub passed from caller or just traverse raw.
    # Better: traverse raw, but substitute knowns. We'll just traverse raw types.
    if isinstance(t, TVar): fvs.add(t.sid)
    elif isinstance(t, Base): pass
    elif isinstance(t, List): free_vars(t.elem, fvs)
    elif isinstance(t, Ref): free_vars(t.elem, fvs)
    elif isinstance(t, Func):
        for a in t.args: free_vars(a, fvs)
        free_vars(t.ret, fvs)
    return fvs

def instantiate(t, sub, new_tvars=None):
    if new_tvars is None: new_tvars = []
    t = follow(t, sub)
    if isinstance(t, TVar):
        new_t = TVar(next_tv_counter[0])
        new_tvars.append(new_t)
        next_tv_counter[0] += 1
        return new_t
    elif isinstance(t, Base): return Base(t.name)
    elif isinstance(t, List): return List(instantiate(t.elem, sub, new_tvars))
    elif isinstance(t, Ref): return Ref(instantiate(t.elem, sub, new_tvars))
    elif isinstance(t, Func):
        return Func(tuple(instantiate(a, sub, new_tvars) for a in t.args),
                    instantiate(t.ret, sub, new_tvars))
    return t

def check_structure(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed")
    elif tag == "fn":
        if len(term) != 3:
            raise ValueError("Malformed")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed")
        if len(set(params)) != len(params):
            raise ValueError("Malformed")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("Malformed")
        check_structure(term[2])
    elif tag == "call":
        if len(term) != 3:
            raise ValueError("Malformed")
        check_structure(term[1])
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed")
        for a in args:
            check_structure(a)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed")
        name = term[1]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed")
        check_structure(term[2])
        check_structure(term[3])
    elif tag == "letrec":
        if len(term) != 4:
            raise ValueError("Malformed")
        name = term[1]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed")
        check_structure(term[2])
        check_structure(term[3])
    elif tag == "nil":
        if len(term) != 1:
            raise ValueError("Malformed")
    elif tag == "cons":
        if len(term) != 3:
            raise ValueError("Malformed")
        check_structure(term[1])
        check_structure(term[2])
    elif tag == "match":
        if len(term) != 6:
            raise ValueError("Malformed")
        check_structure(term[1])
        check_structure(term[2])
        check_structure(term[5])
        hn, tn = term[3], term[4]
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn:
            raise ValueError("Malformed")
        if hn == tn:
            raise ValueError("Malformed")
    elif tag == "ref":
        if len(term) != 2:
            raise ValueError("Malformed")
        check_structure(term[1])
    elif tag == "get":
        if len(term) != 2:
            raise ValueError("Malformed")
        check_structure(term[1])
    elif tag == "set":
        if len(term) != 3:
            raise ValueError("Malformed")
        check_structure(term[1])
        check_structure(term[2])
    else:
        raise ValueError("Malformed")

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit"): return True
    if tag == "var": return True
    if tag == "fn": return True
    if tag == "nil": return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def weak_infer(term):
    check_structure(term)

    next_tv_counter = [0]
    sub = {}
    env = [{}]

    Int = Base('Int')
    Bool = Base('Bool')
    Str = Base('Str')
    Unit = Base('Unit')

    env[0]['plus'] = (Func((Int, Int), Int), False)
    eq_var = TVar(next_tv_counter[0]); next_tv_counter[0] += 1
    env[0]['eq'] = (Func((eq_var, eq_var), Bool), True)
    env[0]['size'] = (Func((Str,), Int), False)

    def infer(term, env, sub):
        tag = term[0]
        if tag == "int":
            return Int
        elif tag == "bool":
            return Bool
        elif tag == "str":
            return Str
        elif tag == "unit":
            return Unit
        elif tag == "var":
            name = term[1]
            for scope in reversed(env):
                if name in scope:
                    t, poly = scope[name]
                    if poly:
                        return instantiate(t, sub)
                    else:
                        return follow(t, sub)
            raise ValueError("Unbound variable")
        elif tag == "fn":
            params, body = term[1], term[2]
            fresh = [TVar(next_tv_counter[0]) for _ in params]
            next_tv_counter[0] += len(params)
            new_env = env + [{p: (tv, False) for p, tv in zip(params, fresh)}]
            ret = infer(body, new_env, sub)
            return Func(tuple(follow(tv, sub) for tv in fresh), ret)
        elif tag == "call":
            f, args = term[1], term[2]
            ft = follow(infer(f, env, sub), sub)
            if not isinstance(ft, Func):
                raise ValueError("Type mismatch")
            if len(ft.args) != len(args):
                raise ValueError("Arity mismatch")
            arg_types = [infer(a, env, sub) for a in args]
            for a, at in zip(ft.args, arg_types):
                unify(a, at, sub)
            return ft.ret
        elif tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            t1 = follow(infer(e1, env, sub), sub)
            is_val = is_value(e1)
            new_env = env + [{name: (t1, is_val)}]
            return infer(e2, new_env, sub)
        elif tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(e1, tuple) or e1[0] != "fn":
                raise ValueError("Malformed")
            name_t = TVar(next_tv_counter[0]); next_tv_counter[0] += 1
            new_env1 = env + [{name: (name_t, False)}]
            t1 = infer(e1, new_env1, sub)
            unify(name_t, t1, sub)
            t1 = follow(t1, sub)
            new_env2 = env + [{name: (t1, True)}]
            return infer(e2, new_env2, sub)
        elif tag == "nil":
            a = TVar(next_tv_counter[0]); next_tv_counter[0] += 1
            return List(a)
        elif tag == "cons":
            h, t = term[1], term[2]
            ht = infer(h, env, sub)
            tt = follow(infer(t, env, sub), sub)
            if not isinstance(tt, List):
                raise ValueError("Type mismatch")
            unify(ht, tt.elem, sub)
            return tt
        elif tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            st = follow(infer(s, env, sub), sub)
            if not isinstance(st, List):
                raise ValueError("Type mismatch")
            elem_t = st.elem
            new_env = env + [{hn: (elem_t, False), tn: (st, False)}]
