    y = follow(y, sub)
    if isinstance(y, TVar) and y.sid == x.sid:
        return
    def occurs(v, t):
        t = follow(t, sub)
        if isinstance(t, TVar):
            return t.sid == v.sid
        if isinstance(t, List): return occurs(v, t.elem)
        if isinstance(t, Ref): return occurs(v, t.elem)
        if isinstance(t, Func):
