            h, t = term[1], term[2]
            ht = infer(h, env, sub)
            tt = follow(infer(t, env, sub), sub)
            if not isinstance(tt, List):
                raise ValueError("Type mismatch")
            unify(ht, tt.elem, sub)
            return tt
        elif tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            st = follow(infer(s, env, sub), sub)
            if not isinstance(st, List):
                raise ValueError("Type mismatch")
            elem_t = st.elem
            new_env = env + [{hn: (elem_t, False, None), tn: (st, False, None)}]
            t_nil = infer(e_nil, new_env, sub)
            t_cons = infer(e_cons, new_env, sub)
            unify(t_nil, t_cons, sub)
            return t_nil
        elif tag == "ref":
            e = term[1]
            return Ref(infer(e, env, sub))
        elif tag == "get":
            r = term[1]
            rt = follow(infer(r, env, sub), sub)
            if not isinstance(rt, Ref):
                raise ValueError("Type mismatch")
            return rt.elem
        elif tag == "set":
            r, e = term[1], term[2]
            rt = follow(infer(r, env, sub), sub)
            if not isinstance(rt, Ref):
                raise ValueError("Type mismatch")
            et = infer(e, env, sub)
            unify(rt.elem, et, sub)
            return Unit
        else:
            raise ValueError("Malformed")

    final_type = follow(infer(term, env, sub), sub)

    name_map = {}
    counter = [1]
    def get_name(sid):
        if sid not in name_map:
            name_map[sid] = f"t{counter[0]}"
            counter[0] += 1
        return name_map[sid]

    def fmt(t):
        t = follow(t, sub)
        if isinstance(t, TVar):
            return get_name(t.sid)
        elif isinstance(t, Base):
            return t.name
        elif isinstance(t, List):
            return f"List<{fmt(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{fmt(t.elem)}>"
        elif isinstance(t, Func):
            if len(t.args) == 1:
                p = fmt(t.args[0])
                if isinstance(follow(t.args[0], sub), Func):
                    p = f"({p})"
                return f"{p} -> {fmt(t.ret)}"
            else:
                ps = ", ".join(fmt(a) for a in t.args)
                return f"({ps}) -> {fmt(t.ret)}"
        return "?"

    return fmt(final_type)

import sys
sys.setrecursionlimit(10000)

class TypeVar:
    def __init__(self, idx):
        self.idx = idx
        self.link = None

    def __repr__(self):
        if self.link is not None:
            return repr(self.link)
        return f't{self.idx}'

    def __eq__(self, other):
        return self is other

    def __hash__(self):
        return id(self)

class Type:
    def __init__(self, kind, args=()):
        self.kind = kind
        self.args = args

    def __repr__(self):
        if self.kind == 'Int': return 'Int'
        if self.kind == 'Bool': return 'Bool'
        if self.kind == 'Str': return 'Str'
        if self.kind == 'Unit': return 'Unit'
        if self.kind == 'List': return f'List<{self.args[0]}>'
        if self.kind == 'Ref': return f'Ref<{self.args[0]}>'
        if self.kind == 'Fn':
            params = self.args[:-1]
            ret = self.args[-1]
            if len(params) == 1:
                p = params[0]
                if isinstance(p, Type) and p.kind == 'Fn':
                    return f'({p}) -> {ret}'
                return f'{p} -> {ret}'
            else:
                params_str = ', '.join(repr(p) for p in params)
                return f'({params_str}) -> {ret}'
        return f'{self.kind}({self.args})'

_tv_counter = 0

def fresh_tv():
    global _tv_counter
    _tv_counter += 1
    return TypeVar(_tv_counter)

def apply_subst(t, subst):
    if isinstance(t, TypeVar):
        if t.link is not None:
            return apply_subst(t.link, subst)
        return t
    elif isinstance(t, Type):
        if t.kind == 'Fn':
            new_args = tuple(apply_subst(arg, subst) for arg in t.args)
            return Type('Fn', new_args)
        else:
            new_args = tuple(apply_subst(arg, subst) for arg in t.args)
            return Type(t.kind, new_args)
    return t

def unify(t1, t2, subst):
    while isinstance(t1, TypeVar) and t1.link is not None:
        t1 = t1.link
    while isinstance(t2, TypeVar) and t2.link is not None:
        t2 = t2.link

    if isinstance(t1, TypeVar) and isinstance(t2, TypeVar):
        if t1 is t2:
            return subst
        if occurs_in(t1, t2):
            raise ValueError("Infinite type")
        if occurs_in(t2, t1):
            raise ValueError("Infinite type")
        subst[t1] = t2
        return subst
    elif isinstance(t1, TypeVar):
        if occurs_in(t1, t2):
            raise ValueError("Infinite type")
        subst[t1] = t2
        return subst
    elif isinstance(t2, TypeVar):
        if occurs_in(t2, t1):
            raise ValueError("Infinite type")
        subst[t2] = t1
        return subst
    elif isinstance(t1, Type) and isinstance(t2, Type):
        if t1.kind != t2.kind:
            raise ValueError("Type mismatch")
        if len(t1.args) != len(t2.args):
            raise ValueError("Type mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            subst = unify(a1, a2, subst)
        return subst
    else:
        raise ValueError("Type mismatch")

def occurs_in(tv, t):
    if isinstance(t, TypeVar):
        return tv is t
    elif isinstance(t, Type):
        if t.kind == 'Fn':
            return any(occurs_in(tv, arg) for arg in t.args)
        else:
            return any(occurs_in(tv, arg) for arg in t.args)
    return False

def free_vars(t):
    if isinstance(t, TypeVar):
        return {t}
    elif isinstance(t, Type):
        if t.kind == 'Fn':
            result = set()
            for arg in t.args:
                result |= free_vars(arg)
            return result
        else:
            result = set()
            for arg in t.args:
                result |= free_vars(arg)
            return result
    return set()

def is_value(term):
    if term[0] in ('int', 'bool', 'str', 'unit', 'var', 'fn', 'nil'):
        return True
    if term[0] == 'cons':
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    return False

def env_free_vars(env):
    result = set()
    for t in env.values():
        result |= free_vars(t)
    return result

def infer(term, env, subst):
    tag = term[0]
    if tag == 'int':
        return Type('Int'), subst
    elif tag == 'bool':
        return Type('Bool'), subst
    elif tag == 'str':
        return Type('Str'), subst
    elif tag == 'unit':
        return Type('Unit'), subst
    elif tag == 'var':
        name = term[1]
        if name not in env:
            raise ValueError(f"Unbound variable: {name}")
        t = env[name]
        return apply_subst(t, subst), subst
    elif tag == 'fn':
        params, body = term[1], term[2]
        param_types = tuple(fresh_tv() for _ in params)
        new_env = dict(env)
        for p, t in zip(params, param_types):
            new_env[p] = t
        body_type, subst = infer(body, new_env, subst)
        fn_type = Type('Fn', param_types + (body_type,))
        return fn_type, subst
    elif tag == 'call':
        f, args = term[1], term[2]
        f_type, subst = infer(f, env, subst)
        if not isinstance(f_type, Type) or f_type.kind != 'Fn':
            raise ValueError("Type mismatch: expected function")
        params = f_type.args[:-1]
        ret = f_type.args[-1]
        if len(args) != len(params):
            raise ValueError("Type mismatch: arity")
        arg_types = []
        for arg in args:
            arg_type, subst = infer(arg, env, subst)
            arg_types.append(arg_type)
        for p, a in zip(params, arg_types):
            subst = unify(p, a, subst)
        return ret, subst
    elif tag == 'let':
        name, e1, e2 = term[1], term[2], term[3]
        e1_type, subst = infer(e1, env, subst)
        if is_value(e1):
            e1_type = apply_subst(e1_type, subst)
            env_free = env_free_vars(env)
            # Generalize: keep variables not in env_free
            # In our implementation, we just keep the type as is
            # but we need to track which vars are generalized
            # For simplicity, we'll just use the type directly
            new_env = dict(env)
            new_env[name] = e1_type
        else:
            new_env = dict(env)
            new_env[name] = apply_subst(e1_type, subst)
        e2_type, subst = infer(e2, new_env, subst)
        return e2_type, subst
    elif tag == 'letrec':
        name, e1, e2 = term[1], term[2], term[3]
        if e1[0] != 'fn':
            raise ValueError("letrec requires fn term")
        rec_type = fresh_tv()
        new_env = dict(env)
        new_env[name] = rec_type
        e1_type, subst = infer(e1, new_env, subst)
        if not isinstance(e1_type, Type) or e1_type.kind != 'Fn':
            raise ValueError("Type mismatch: letrec requires function")
        subst = unify(rec_type, e1_type, subst)
        e1_type = apply_subst(e1_type, subst)
        env_free = env_free_vars(env)
        new_env[name] = e1_type
        e2_type, subst = infer(e2, new_env, subst)
        return e2_type, subst
    elif tag == 'nil':
        t = fresh_tv()
        return Type('List', (t,)), subst
    elif tag == 'cons':
        h, t = term[1], term[2]
        h_type, subst = infer(h, env, subst)
        t_type, subst = infer(t, env, subst)
        if not isinstance(t_type, Type) or t_type.kind != 'List':
            raise ValueError("Type mismatch: expected List")
        list_elem = t_type.args[0]
        subst = unify(h_type, list_elem, subst)
        return t_type, subst
    elif tag == 'match':
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type, subst = infer(s, env, subst)
        if not isinstance(s_type, Type) or s_type.kind != 'List':
            raise ValueError("Type mismatch: expected List")
        A = s_type.args[0]
        if hn == tn:
            raise ValueError("match bound names must differ")
        new_env = dict(env)
        new_env[hn] = A
        new_env[tn] = Type('List', (A,))
        e_nil_type, subst = infer(e_nil, new_env, subst)
        e_cons_type, subst = infer(e_cons, new_env, subst)
        subst = unify(e_nil_type, e_cons_type, subst)
        return e_nil_type, subst
    elif tag == 'ref':
        e, = term[1]
        e_type, subst = infer(e, env, subst)
        return Type('Ref', (e_type,)), subst
    elif tag == 'get':
        r, = term[1]
        r_type, subst = infer(r, env, subst)
        if not isinstance(r_type, Type) or r_type.kind != 'Ref':
            raise ValueError("Type mismatch: expected Ref")
        return r_type.args[0], subst
    elif tag == 'set':
        r, e = term[1], term[2]
        r_type, subst = infer(r, env, subst)
        if not isinstance(r_type, Type) or r_type.kind != 'Ref':
            raise ValueError("Type mismatch: expected Ref")
        content_type = r_type.args[0]
        e_type, subst = infer(e, env, subst)
        subst = unify(content_type, e_type, subst)
        return Type('Unit'), subst
    else:
        raise ValueError(f"Unknown tag: {tag}")

def weak_infer(term):
    global _tv_counter
    _tv_counter = 0

    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag must be string")

    known_tags = {'int', 'bool', 'str', 'unit', 'var', 'fn', 'call', 'let', 'letrec', 
                  'nil', 'cons', 'match', 'ref', 'get', 'set'}
    if tag not in known_tags:
        raise ValueError(f"Unknown tag: {tag}")

    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int term")
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool term")
    elif tag == 'str':
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str term")
    elif tag == 'unit':
        if len(term) != 1:
            raise ValueError("Malformed unit term")
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Malformed var term")
    elif tag == 'fn':
        if len(term) != 3:
            raise ValueError("Malformed fn term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params must be non-empty tuple")
        if any(not isinstance(p, str) or len(p) == 0 for p in params):
            raise ValueError("fn params must be non-empty strings")
        if len(set(params)) != len(params):
            raise ValueError("fn params must be distinct")
        weak_infer(body)
    elif tag == 'call':
        if len(term) != 3:
            raise ValueError("Malformed call term")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        weak_infer(f)
        for arg in args:
            weak_infer(arg)
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed let term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("let name must be non-empty string")
        weak_infer(e1)
        weak_infer(e2)
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed letrec term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0:
            raise ValueError("letrec name must be non-empty string")
        if e1[0] != 'fn':
            raise ValueError("letrec requires fn term")
        weak_infer(e1)
        weak_infer(e2)
    elif tag == 'nil':
        if len(term) != 1:
            raise ValueError("Malformed nil term")
    elif tag == 'cons':
        if len(term) != 3:
            raise ValueError("Malformed cons term")
        h, t = term[1], term[2]
        weak_infer(h)
        weak_infer(t)
    elif tag == 'match':
        if len(term) != 6:
            raise ValueError("Malformed match term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or len(hn) == 0:
            raise ValueError("match hn must be non-empty string")
        if not isinstance(tn, str) or len(tn) == 0:
            raise ValueError("match tn must be non-empty string")
        if hn == tn:
            raise ValueError("match bound names must differ")
        weak_infer(s)
        weak_infer(e_nil)
        weak_infer(e_cons)
    elif tag == 'ref':
        if len(term) != 2:
            raise ValueError("Malformed ref term")
        weak_infer(term[1])
    elif tag == 'get':
        if len(term) != 2:
            raise ValueError("Malformed get term")
        weak_infer(term[1])
    elif tag == 'set':
        if len(term) != 3:
            raise ValueError("Malformed set term")
        weak_infer(term[1])
        weak_infer(term[2])

    env = {
        'plus': Type('Fn', (Type('Int'), Type('Int'), Type('Int'))),
        'eq': Type('Fn', (fresh_tv(), fresh_tv(), Type('Bool'))),
        'size': Type('Fn', (Type('Str'), Type('Int')))
    }

    try:
        result_type, subst = infer(term, env, {})
        result_type = apply_subst(result_type, subst)
        return repr(result_type)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

def weak_infer(term):
    # --- Validation ---
    def validate(t):
        if not isinstance(t, tuple) or len(t) == 0:
            raise ValueError("Malformed")
        tag = t[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")
        if tag == 'int':
            if len(t) != 2 or not isinstance(t[1], int) or isinstance(t[1], bool): raise ValueError("Malformed")
        elif tag == 'bool':
            if len(t) != 2 or not isinstance(t[1], bool): raise ValueError("Malformed")
        elif tag == 'str':
            if len(t) != 2 or not isinstance(t[1], str): raise ValueError("Malformed")
        elif tag == 'unit':
            if len(t) != 1: raise ValueError("Malformed")
        elif tag == 'var':
            if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
        elif tag == 'fn':
            if len(t) != 4 or not isinstance(t[1], tuple) or len(t[1]) == 0: raise ValueError("Malformed")
            for p in t[1]:
                if not isinstance(p, str) or not p: raise ValueError("Malformed")
            if len(set(t[1])) != len(t[1]): raise ValueError("Malformed")
        elif tag == 'call':
            if len(t) != 3 or not isinstance(t[2], tuple) or len(t[2]) == 0: raise ValueError("Malformed")
        elif tag == 'let':
            if len(t) != 4 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
        elif tag == 'letrec':
            if len(t) != 4 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
        elif tag == 'nil':
            if len(t) != 1: raise ValueError("Malformed")
        elif tag == 'cons':
            if len(t) != 3: raise ValueError("Malformed")
        elif tag == 'match':
            if len(t) != 6: raise ValueError("Malformed")
            if not isinstance(t[2], str) or not t[2]: raise ValueError("Malformed")
            if not isinstance(t[3], str) or not t[3]: raise ValueError("Malformed")
            if t[2] == t[3]: raise ValueError("Malformed")
        elif tag == 'ref':
            if len(t) != 2: raise ValueError("Malformed")
        elif tag == 'get':
            if len(t) != 2: raise ValueError("Malformed")
        elif tag == 'set':
            if len(t) != 3: raise ValueError("Malformed")
        else:
            raise ValueError("Unknown tag")
        # Recursively validate subterms
        if tag == 'fn':
            validate(t[3])
        elif tag == 'call':
            validate(t[1])
            for a in t[2]: validate(a)
        elif tag == 'cons':
            validate(t[1]); validate(t[2])
        elif tag == 'match':
            validate(t[0]); validate(t[2]); validate(t[4])
        elif tag == 'let':
            validate(t[1]); validate(t[3])
        elif tag == 'letrec':
            validate(t[1]); validate(t[3])
        elif tag == 'ref':
            validate(t[1])
        elif tag == 'get':
            validate(t[1])
        elif tag == 'set':
            validate(t[1]); validate(t[2])

    validate(term)

    # --- Type System ---
    fresh_counter = [0]
    def fresh():
        fresh_counter[0] += 1
        return ('Var', fresh_counter[0])

    def apply_sub(sub, t):
        if t[0] == 'Var' and t[1] in sub:
            return apply_sub(sub, sub[t[1]])
        if t[0] == 'Fun':
            return ('Fun', tuple(apply_sub(sub, p) for p in t[1]), apply_sub(sub, t[2]))
        if t[0] in ('List', 'Ref'):
            return (t[0], apply_sub(sub, t[1]))
        return t

    def occurs(v, t):
        if t[0] == 'Var': return t[1] == v
        if t[0] == 'Fun': return any(occurs(v, p) for p in t[1]) or occurs(v, t[2])
        if t[0] in ('List', 'Ref'): return occurs(v, t[1])
        return False

    def unify(t1, t2, sub):
        t1 = apply_sub(sub, t1)
        t2 = apply_sub(sub, t2)
        if t1 == t2: return sub
        if t1[0] == 'Var':
            v = t1[1]
            if occurs(v, t2): raise ValueError("Infinite type")
            return {**sub, v: t2}
        if t2[0] == 'Var':
            v = t2[1]
            if occurs(v, t1): raise ValueError("Infinite type")
            return {**sub, v: t1}
        if t1[0] != t2[0]: raise ValueError("Type mismatch")
        if t1[0] == 'Fun':
            if len(t1[1]) != len(t2[1]): raise ValueError("Arity mismatch")
            s = sub
            for p1, p2 in zip(t1[1], t2[1]):
                s = unify(p1, p2, s)
            return unify(t1[2], t2[2], s)
        if t1[0] in ('List', 'Ref'):
            return unify(t1[1], t2[1], sub)
        raise ValueError("Type mismatch")

    def free_vars(t):
        if t[0] == 'Var': return {t[1]}
        if t[0] == 'Fun':
            vs = set()
            for p in t[1]: vs |= free_vars(p)
            vs |= free_vars(t[2])
            return vs
        if t[0] in ('List', 'Ref'): return free_vars(t[1])
        return set()

    def env_free_vars(env):
        vs = set()
        for d in env:
            for t in d.values():
                vs |= free_vars(t)
        return vs

    def gen(env, t):
        free = free_vars(t)
        env_vs = env_free_vars(env)
        quantify = free - env_vs
        if not quantify: return t
        return ('ForAll', tuple(sorted(quantify)), t)

    def spec(t):
        if t[0] == 'ForAll':
            vs, t0 = t[1], t[2]
            return apply_sub({v: fresh() for v in vs}, t0)
        return t

    def lookup(name, env):
        for d in env:
            if name in d:
                return spec(d[name])
        raise ValueError("Unbound variable")

    def is_value(term):
        if term[0] in ('int', 'bool', 'str', 'unit', 'var', 'fn', 'nil'): return True
        if term[0] == 'cons': return is_value(term[1]) and is_value(term[2])
        return False

    # --- Inference ---
    def infer(term, env, sub):
        tag = term[0]
        if tag == 'int': return ('Int',), sub
        if tag == 'bool': return ('Bool',), sub
        if tag == 'str': return ('Str',), sub
        if tag == 'unit': return ('Unit',), sub
        if tag == 'var':
            t = lookup(term[1], env)
            return apply_sub(sub, t), sub
        if tag == 'fn':
            params = term[1]
            body = term[3]
            fresh_types = tuple(fresh() for _ in params)
            new_env = [{p: ft for p, ft in zip(params, fresh_types)}] + env
            t_body, sub2 = infer(body, new_env, sub)
            return ('Fun', fresh_types, t_body), sub2
        if tag == 'call':
            f, args = term[1], term[2]
            t_f, sub1 = infer(f, env, sub)
            t_f = apply_sub(sub1, t_f)
            if t_f[0] != 'Fun': raise ValueError("Type mismatch")
            params, res = t_f[1], t_f[2]
            if len(args) != len(params): raise ValueError("Arity mismatch")
            sub2 = sub1
            t_args = []
            for a in args:
                t_a, sub2 = infer(a, env, sub2)
                t_args.append(t_a)
            for p, t_a in zip(params, t_args):
                sub2 = unify(p, t_a, sub2)
            return apply_sub(sub2, res), sub2
        if tag == 'let':
            name, e1, e2 = term[1], term[2], term[3]
            t1, sub1 = infer(e1, env, sub)
            t1 = apply_sub(sub1, t1)
            t_gen = gen(env, t1) if is_value(e1) else t1
            new_env = [{name: t_gen}] + env
            return infer(e2, new_env, sub1)
        if tag == 'letrec':
            name, e1, e2 = term[1], term[2], term[3]
            if e1[0] != 'fn': raise ValueError("Malformed")
            placeholder = fresh()
            new_env = [{name: placeholder}] + env
            t1, sub1 = infer(e1, new_env, sub)
            sub1 = unify(placeholder, t1, sub1)
            t1 = apply_sub(sub1, t1)
            t_gen = gen(env, t1)
            new_env2 = [{name: t_gen}] + env
            return infer(e2, new_env2, sub1)
        if tag == 'nil':
            return ('List', fresh()), sub
        if tag == 'cons':
            h, t = term[1], term[2]
            th, sub1 = infer(h, env, sub)
            tt, sub2 = infer(t, env, sub1)
            return unify(('List', th), tt, sub2), sub2
        if tag == 'match':
            s, e_nil, hn, tn, e_cons = term[0], term[1], term[2], term[3], term[4]
            ts, sub1 = infer(s, env, sub)
            ts = apply_sub(sub1, ts)
            A = fresh()
            sub2 = unify(('List', A), ts, sub1)
            new_env = [{hn: A, tn: ('List', A)}] + env
            t_nil, sub3 = infer(e_nil, new_env, sub2)
            t_cons, sub4 = infer(e_cons, new_env, sub3)
            sub5 = unify(t_nil, t_cons, sub4)
            return apply_sub(sub5, t_cons), sub5
        if tag == 'ref':
            e = term[1]
            t, sub1 = infer(e, env, sub)
            return ('Ref', t), sub1
        if tag == 'get':
            r = term[1]
            tr, sub1 = infer(r, env, sub)
            tr = apply_sub(sub1, tr)
            A = fresh()
            sub2 = unify(tr, ('Ref', A), sub1)
            return apply_sub(sub2, A), sub2
        if tag == 'set':
            r, e = term[1], term[2]
            tr, sub1 = infer(r, env, sub)
            te, sub2 = infer(e, env, sub1)
            tr = apply_sub(sub2, tr)
            A = fresh()
            sub3 = unify(tr, ('Ref', A), sub2)
            sub4 = unify(te, A, sub3)
            return ('Unit',), sub4
        raise ValueError("Unknown tag")

    # --- Execution ---
    env = [
        {'plus': ('Fun', ('Int', 'Int'), 'Int'),
         'eq': ('Fun', ('Var', 1), ('Var', 1), 'Bool'), # eq: (a,a)->Bool handled via unify
