         'size': ('Fun', ('Str',), ('Int',))}
    ]
    # Actually, let's just build env correctly inside the function or predefine properly.
    # I'll redefine env construction cleanly:
    env = [
        {'plus': ('Fun', ('Int', 'Int'), ('Int',)),
         'eq': ('Fun', ('Var', 1), ('Var', 1), ('Bool',)),
         'size': ('Fun', ('Str',), ('Int',))}
    ]
    # But 'Var',1 might clash with fresh vars. I'll use a different initial var ID or just handle it.
