            'eq': ('Fun', ('Var', 999), ('Var', 999), ('Bool',)),
            'size': ('Fun', ('Str',), ('Int',))}]
    fresh_counter[0] = 1000 # Avoid clash

    final_type, _ = infer(term, env, {})

    # --- Formatting ---
    def get_first_appearance_order(t):
        seen = []
        def collect(tt):
            if tt[0] == 'Var':
                if tt[1] not in seen: seen.append(tt[1])
            elif tt[0] == 'Fun':
                for p in tt[1]: collect(p)
                collect(tt[2])
            elif tt[0] in ('List', 'Ref'):
                collect(tt[1])
        collect(t)
        return {v: i+1 for i, v in enumerate(seen)}

    var_map = get_first_appearance_order(final_type)

    def fmt(t):
        if t[0] == 'Int': return 'Int'
        if t[0] == 'Bool': return 'Bool'
        if t[0] == 'Str': return 'Str'
        if t[0] == 'Unit': return 'Unit'
        if t[0] == 'Var': return f"t{var_map[t[1]]}"
        if t[0] == 'List': return f"List<{fmt(t[1])}>"
        if t[0] == 'Ref': return f"Ref<{fmt(t[1])}>"
        if t[0] == 'Fun':
            params, res = t[1], t[2]
            if len(params) == 1:
                p = fmt(params[0])
                if params[0][0] == 'Fun': p = f"({p})"
                return f"{p} -> {fmt(res)}"
            else:
                ps = ", ".join(fmt(p) for p in params)
                return f"({ps}) -> {fmt(res)}"
        return str(t)

    return fmt(final_type)

class Type:
    def __eq__(self, other):
        if not isinstance(other, Type): return False
        if type(self) != type(other): return False
        if isinstance(self, TVar): return self.uid == other.uid
        if isinstance(self, TPrim): return self.kind == other.kind
        if isinstance(self, TFunc): return self.args == other.args and self.ret == other.ret
        if isinstance(self, TList): return self.elem == other.elem
        if isinstance(self, TRef): return self.content == other.content
        return False

class TVar(Type):
    def __init__(self, uid): self.uid = uid
    def __hash__(self): return hash(self.uid)
    def free(self): return {self}

class TPrim(Type):
    def __init__(self, kind): self.kind = kind
    def free(self): return set()

class TFunc(Type):
    def __init__(self, args, ret): self.args = args; self.ret = ret
    def free(self): return set().union(*(t.free() for t in self.args), self.ret.free())

class TList(Type):
    def __init__(self, elem): self.elem = elem
    def free(self): return self.elem.free()

class TRef(Type):
    def __init__(self, content): self.content = content
    def free(self): return self.content.free()

def _apply_sub(sub, t):
    if isinstance(t, TVar): return sub.get(t, t)
    if isinstance(t, TFunc): return TFunc([_apply_sub(sub, a) for a in t.args], _apply_sub(sub, t.ret))
    if isinstance(t, TList): return TList(_apply_sub(sub, t.elem))
    if isinstance(t, TRef): return TRef(_apply_sub(sub, t.content))
    return t

def _collect_uids(t):
    if isinstance(t, TVar): return {t.uid}
    if isinstance(t, TPrim): return set()
    if isinstance(t, TFunc):
        uids = set()
        for a in t.args: uids |= _collect_uids(a)
        uids |= _collect_uids(t.ret)
        return uids
    if isinstance(t, TList): return _collect_uids(t.elem)
    if isinstance(t, TRef): return _collect_uids(t.content)
    return set()

def _fmt(t, var_map):
    if isinstance(t, TVar): return f"t{var_map[t.uid]}"
    if isinstance(t, TPrim): return t.kind
    if isinstance(t, TList): return f"List<{_fmt(t.elem, var_map)}>"
    if isinstance(t, TRef): return f"Ref<{_fmt(t.content, var_map)}>"
    if isinstance(t, TFunc):
        args_str = ", ".join(_fmt(a, var_map) for a in t.args)
        ret_str = _fmt(t.ret, var_map)
        if len(t.args) == 1:
            p = _fmt(t.args[0], var_map)
            if isinstance(t.args[0], TFunc): return f"({p}) -> {ret_str}"
            return f"{p} -> {ret_str}"
        return f"({args_str}) -> {ret_str}"
    return ""

def _validate(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed term")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed term")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed term")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed term")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Malformed term")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed term")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed term")
        if len(set(params)) != len(params): raise ValueError("Malformed term")
        if not all(isinstance(p, str) and len(p) > 0 for p in params): raise ValueError("Malformed term")
        _validate(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed term")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed term")
        _validate(f)
        for a in args: _validate(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed term")
        _validate(e1); _validate(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed term")
        _validate(e1); _validate(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed term")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed term")
        _validate(term[1]); _validate(term[2])
    elif tag == "match":
        if len(term) != 6: raise ValueError("Malformed term")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or len(hn) == 0: raise ValueError("Malformed term")
        if not isinstance(tn, str) or len(tn) == 0: raise ValueError("Malformed term")
        if hn == tn: raise ValueError("Malformed term")
        _validate(s); _validate(e_nil); _validate(e_cons)
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed term")
        _validate(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed term")
        _validate(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed term")
        _validate(term[1]); _validate(term[2])
    else:
        raise ValueError("Malformed term")

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"): return True
    if tag == "cons": return is_value(term[1]) and is_value(term[2])
    return False

class TypeInferencer:
    def __init__(self):
        self.sub = {}
        self.fresh_counter = 0
        self.env = [{}]
        self._init_env()

    def _init_env(self):
        int_t, bool_t, str_t = TPrim('Int'), TPrim('Bool'), TPrim('Str')
        t0 = self.fresh_var()
        self.env[0]['+'] = (TFunc([int_t, int_t], int_t), frozenset())
        self.env[0]['eq'] = (TFunc([t0, t0], bool_t), frozenset({t0}))
        self.env[0]['size'] = (TFunc([str_t], int_t), frozenset())

    def fresh_var(self):
        uid = self.fresh_counter
        self.fresh_counter += 1
        return TVar(uid)

    def apply(self, subs, t):
        return _apply_sub(subs, t)

    def lookup(self, name):
        for scope in reversed(self.env):
            if name in scope:
                val = scope[name]
                if isinstance(val, tuple):
                    t, fv = val
                    fresh_map = {v: self.fresh_var() for v in fv}
                    new_t = self.apply(fresh_map, t)
                    for old_v, new_v in fresh_map.items():
                        if old_v in self.sub:
                            self.sub[new_v] = self.apply(self.sub, self.sub[old_v])
                            del self.sub[old_v]
                    return new_t
                else:
                    return val
        raise ValueError("Unbound variable")

    def unify(self, t1, t2):
        t1 = self.apply(self.sub, t1)
        t2 = self.apply(self.sub, t2)
        if t1 == t2: return
        if isinstance(t1, TVar):
            if t1 in self.sub: return self.unify(self.sub[t1], t2)
            if t1 in t2.free(): raise ValueError("Infinite type")
            self.sub[t1] = t2
            return
        if isinstance(t2, TVar):
            if t2 in self.sub: return self.unify(t1, self.sub[t2])
            if t2 in t1.free(): raise ValueError("Infinite type")
            self.sub[t2] = t1
            return
        if isinstance(t1, TFunc) and isinstance(t2, TFunc):
            if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
            for a1, a2 in zip(t1.args, t2.args):
                self.unify(a1, a2)
            self.unify(t1.ret, t2.ret)
            return
        if isinstance(t1, TList) and isinstance(t2, TList):
            self.unify(t1.elem, t2.elem)
            return
        if isinstance(t1, TRef) and isinstance(t2, TRef):
            self.unify(t1.content, t2.content)
            return
        raise ValueError("Type mismatch")

    def generalize(self, t):
        env_fv = set()
        for scope in self.env:
            for _, fv in scope.items():
                if isinstance(fv, tuple): env_fv |= fv[1]
        return (t, env_fv)

    def infer(self, term):
        tag = term[0]
        if tag == "int": return TPrim('Int')
        if tag == "bool": return TPrim('Bool')
        if tag == "str": return TPrim('Str')
        if tag == "unit": return TPrim('Unit')
        if tag == "var": return self.lookup(term[1])
        if tag == "fn":
            params, body = term[1], term[2]
            param_types = [self.fresh_var() for _ in params]
            self.env.append({p: t for p, t in zip(params, param_types)})
            body_type = self.infer(body)
            self.env.pop()
            return TFunc(param_types, body_type)
        if tag == "call":
            f, args = term[1], term[2]
            f_type = self.infer(f)
            arg_types = [self.infer(a) for a in args]
            ret_type = self.fresh_var()
            self.unify(f_type, TFunc(arg_types, ret_type))
            return ret_type
        if tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            t1 = self.infer(e1)
            if is_value(e1):
                scheme = self.generalize(t1)
            else:
                scheme = t1
            self.env[-1][name] = scheme
            return self.infer(e2)
        if tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            if tag != "fn": raise ValueError("letrec requires fn")
            t1 = self.infer(e1)
            scheme = self.generalize(t1)
            self.env[-1][name] = scheme
            return self.infer(e2)
        if tag == "nil":
            return TList(self.fresh_var())
        if tag == "cons":
            h, t = term[1], term[2]
            t_h = self.infer(h)
            t_t = self.infer(t)
            self.unify(t_t, TList(t_h))
            return TList(t_h)
        if tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            t_s = self.infer(s)
            A = self.fresh_var()
            self.unify(t_s, TList(A))
            self.env[-1][hn] = A
            self.env[-1][tn] = TList(A)
            t_nil = self.infer(e_nil)
            t_cons = self.infer(e_cons)
            self.unify(t_nil, t_cons)
            self.env.pop()
            return t_nil
        if tag == "ref":
            t = self.infer(term[1])
            return TRef(t)
        if tag == "get":
            t_r = self.infer(term[1])
            t = self.fresh_var()
            self.unify(t_r, TRef(t))
            return t
        if tag == "set":
            r, e = term[1], term[2]
            t_r = self.infer(r)
            t_e = self.infer(e)
            t = self.fresh_var()
            self.unify(t_r, TRef(t))
            self.unify(t_e, TPrim('Unit')) # Wait, set has type Unit, e must match content type
            # Correction: set needs e to have content type of r.
            # Let's redo set/unify properly:
            pass
        # Fix set logic inline:
        if tag == "set":
            r, e = term[1], term[2]
            t_r = self.infer(r)
            t_e = self.infer(e)
            t = self.fresh_var()
            self.unify(t_r, TRef(t))
            self.unify(t_e, t)
            return TPrim('Unit')
        raise ValueError("Unknown tag")

def weak_infer(term):
    _validate(term)
    inf = TypeInferencer()
    res = inf.infer(term)
    final = inf.apply(inf.sub, res)
    uids = sorted(_collect_uids(final))
    var_map = {uid: i + 1 for i, uid in enumerate(uids)}
    return _fmt(final, var_map)

import sys

class TVar:
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return f"t{self.id+1}"

class TBase:
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return self.name

class TList:
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"List<{self.elem}>"

class TRef:
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self):
        return f"Ref<{self.elem}>"

class TFunc:
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret
    def __repr__(self):
        if len(self.params) == 1:
            p = self.params[0]
            if isinstance(p, TFunc):
                return f"({p}) -> {self.ret}"
            return f"{p} -> {self.ret}"
        ps = ", ".join(str(p) for p in self.params)
        return f"({ps}) -> {self.ret}"

class TypeScheme:
    def __init__(self, type_, quantified):
        self.type = type_
        self.quantified = quantified

_tv_counter = 0
def fresh():
    global _tv_counter
    t = TVar(_tv_counter)
    _tv_counter += 1
    return t

def free_vars(t):
    if isinstance(t, TVar): return {t}
    if isinstance(t, TBase): return set()
    if isinstance(t, TList): return free_vars(t.elem)
    if isinstance(t, TRef): return free_vars(t.elem)
    if isinstance(t, TFunc):
        res = set()
        for p in t.params: res |= free_vars(p)
        res |= free_vars(t.ret)
        return res
    return set()

def apply_subst(t, subst):
    if isinstance(t, TVar): return subst.get(t, t)
    if isinstance(t, TBase): return t
    if isinstance(t, TList): return TList(apply_subst(t.elem, subst))
    if isinstance(t, TRef): return TRef(apply_subst(t.elem, subst))
    if isinstance(t, TFunc):
        return TFunc([apply_subst(p, subst) for p in t.params], apply_subst(t.ret, subst))
    return t

def occurs(v, t):
    if isinstance(t, TVar): return v is t
    if isinstance(t, TList): return occurs(v, t.elem)
    if isinstance(t, TRef): return occurs(v, t.elem)
    if isinstance(t, TFunc):
        return any(occurs(v, p) for p in t.params) or occurs(v, t.ret)
    return False

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if t1 is t2: return subst
    if isinstance(t1, TVar):
        if occurs(t1, t2): raise ValueError("Infinite type")
        return {**subst, t1: t2}
    if isinstance(t2, TVar):
        if occurs(t2, t1): raise ValueError("Infinite type")
        return {**subst, t2: t1}
    if isinstance(t1, TBase) and isinstance(t2, TBase) and t1.name == t2.name: return subst
    if isinstance(t1, TList) and isinstance(t2, TList): return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TRef) and isinstance(t2, TRef): return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        if len(t1.params) != len(t2.params): raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            subst = unify(p1, p2, subst)
        return unify(t1.ret, t2.ret, subst)
    raise ValueError("Type mismatch")

def generalize(env, t):
    qvars = [v for v in free_vars(t) if v not in env]
    return TypeScheme(t, set(qvars))

def instantiate(scheme):
    subst = {}
    for v in scheme.quantified:
        subst[v] = fresh()
    return apply_subst(scheme.type, subst)

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError("Malformed")
    elif tag == "unit":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
        if len(set(params)) != len(params): raise ValueError("Malformed")
        for p in params:
            if not isinstance(p, str) or not p: raise ValueError("Malformed")
        validate(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed")
        validate(term[1])
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed")
        for a in args: validate(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        name = term[1]
        if not isinstance(name, str) or not name: raise ValueError("Malformed")
        validate(term[2]); validate(term[3])
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed")
        name = term[1]
        if not isinstance(name, str) or not name: raise ValueError("Malformed")
        validate(term[2]); validate(term[3])
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed")
