def is_value(term):
    if not isinstance(term, tuple): return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit"): return True
    if tag == "var": return True
    if tag == "fn": return True
    if tag == "nil": return True
    if tag == "cons": return is_value(term[1]) and is_value(term[2])
    return False

def infer(term, env):
    validate(term)
    tag = term[0]
    if tag == "int": return TBase("Int"), env
    if tag == "bool": return TBase("Bool"), env
    if tag == "str": return TBase("Str"), env
    if tag == "unit": return TBase("Unit"), env
    if tag == "var":
        name = term[1]
        if name not in env: raise ValueError("Unbound variable")
        return instantiate(env[name]), env
    if tag == "fn":
        params, body = term[1], term[2]
        new_env = {}
        for p in params:
            new_env[p] = TypeScheme(fresh(), set())
        body_type, env2 = infer(body, {**env, **new_env})
        return TFunc([v.type for v in new_env.values()], body_type), env
    if tag == "call":
        f, args = term[1], term[2]
        f_type, env_f = infer(f, env)
        if not isinstance(f_type, TFunc): raise ValueError("Arity mismatch")
        if len(args) != len(f_type.params): raise ValueError("Arity mismatch")
        inst_f = instantiate(TypeScheme(f_type, free_vars(f_type)))
        subst = {}
        for arg, param in zip(args, inst_f.params):
            arg_type, _ = infer(arg, env)
            subst = unify(arg_type, param, subst)
        ret = apply_subst(inst_f.ret, subst)
        return ret, env
    if tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type, env1 = infer(e1, env)
        val = is_value(e1)
        scheme = generalize(env, e1_type) if val else TypeScheme(e1_type, set())
        new_env = {**env, name: scheme}
        return infer(e2, new_env)
    if tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(e1, tuple) or e1[0] != "fn": raise ValueError("Malformed")
        rec_type = fresh()
        scheme_rec = TypeScheme(rec_type, set())
        env1 = {**env, name: scheme_rec}
        e1_type, env2 = infer(e1, env1)
        unify(rec_type, e1_type, {})
        scheme = generalize(env, e1_type)
        new_env = {**env, name: scheme}
        return infer(e2, new_env)
    if tag == "nil":
        return TList(fresh()), env
    if tag == "cons":
        h, t = term[1], term[2]
        h_type, env_h = infer(h, env)
        t_type, env_t = infer(t, env)
        if not isinstance(t_type, TList): raise ValueError("Type mismatch")
        unify(h_type, t_type.elem, {})
        return t_type, env_t
    if tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type, env_s = infer(s, env)
        if not isinstance(s_type, TList): raise ValueError("Type mismatch")
        elem_type = s_type.elem
        new_env = {**env_s, hn: TypeScheme(elem_type, set()), tn: TypeScheme(s_type, set())}
        nil_type, env_nil = infer(e_nil, new_env)
        cons_type, env_cons = infer(e_cons, new_env)
        unify(nil_type, cons_type, {})
        return nil_type, env_cons
    if tag == "ref":
        e, = term[1]
        e_type, _ = infer(e, env)
        return TRef(e_type), env
    if tag == "get":
        r, = term[1]
        r_type, _ = infer(r, env)
        if not isinstance(r_type, TRef): raise ValueError("Type mismatch")
        return r_type.elem, env
    if tag == "set":
        r, e = term[1], term[2]
        r_type, env_r = infer(r, env)
        if not isinstance(r_type, TRef): raise ValueError("Type mismatch")
        e_type, _ = infer(e, env)
        unify(r_type.elem, e_type, {})
        return TBase("Unit"), env_r
    raise ValueError("Malformed")

def weak_infer(term):
    global _tv_counter
    _tv_counter = 0
    tv_eq = fresh()
    init_env = {
        "plus": TypeScheme(TFunc([TBase("Int"), TBase("Int")], TBase("Int")), set()),
        "eq": TypeScheme(TFunc([tv_eq, tv_eq], TBase("Bool")), {tv_eq}),
        "size": TypeScheme(TFunc([TBase("Str")], TBase("Int")), set())
    }
    final_type, _ = infer(term, init_env)
    all_vars = free_vars(final_type)
    sorted_vars = sorted(all_vars, key=lambda v: v.id)
    var_map = {v: TVar(i) for i, v in enumerate(sorted_vars)}
    def replace_vars(t):
        if isinstance(t, TVar): return var_map.get(t, t)
        if isinstance(t, TBase): return t
        if isinstance(t, TList): return TList(replace_vars(t.elem))
        if isinstance(t, TRef): return TRef(replace_vars(t.elem))
        if isinstance(t, TFunc):
            return TFunc([replace_vars(p) for p in t.params], replace_vars(t.ret))
        return t
    result = replace_vars(final_type)
    return str(result)

