    tv = TVar(_fresh_idx)
    _fresh_idx += 1
    return tv

def apply_subst(t, subst):
    if isinstance(t, TVar):
        if t in subst:
            return apply_subst(subst[t], subst)
        return t
    if isinstance(t, TList):
        return TList(apply_subst(t.elem, subst))
    if isinstance(t, TRef):
        return TRef(apply_subst(t.elem, subst))
    if isinstance(t, TArrow):
        return TArrow(tuple(apply_subst(a, subst) for a in t.args), apply_subst(t.ret, subst))
    return t

def occurs_check(v, t, subst):
    t = apply_subst(t, subst)
    if isinstance(t, TVar):
        return t == v
    if isinstance(t, TList):
        return occurs_check(v, t.elem, subst)
    if isinstance(t, TRef):
        return occurs_check(v, t.elem, subst)
    if isinstance(t, TArrow):
        return any(occurs_check(v, a, subst) for a in t.args) or occurs_check(v, t.ret, subst)
    return False

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if t1 == t2:
        return subst
    if isinstance(t1, TVar):
        if occurs_check(t1, t2, subst):
            raise ValueError("Infinite type")
        return {**subst, t1: t2}
    if isinstance(t2, TVar):
        if occurs_check(t2, t1, subst):
            raise ValueError("Infinite type")
        return {**subst, t2: t1}
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TRef) and isinstance(t2, TRef):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TArrow) and isinstance(t2, TArrow):
        if len(t1.args) != len(t2.args):
            raise ValueError("Arity mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            subst = unify(a1, a2, subst)
        return unify(t1.ret, t2.ret, subst)
    raise ValueError("Type mismatch")

def free_vars(t):
    if isinstance(t, TVar):
        return {t}
    if isinstance(t, TList):
        return free_vars(t.elem)
    if isinstance(t, TRef):
        return free_vars(t.elem)
    if isinstance(t, TArrow):
        res = set()
        for a in t.args:
            res |= free_vars(a)
        res |= free_vars(t.ret)
        return res
    return set()

def free_vars_env(env):
    res = set()
    for t in env.values():
        res |= free_vars(t)
    return res

