def print_type(t):
    t = apply_subst(t, {})
    vars_list = []
    def collect_vars(typ):
        if isinstance(typ, TVar):
            if typ not in vars_list:
                vars_list.append(typ)
        elif isinstance(typ, TList):
            collect_vars(typ.elem)
        elif isinstance(typ, TRef):
            collect_vars(typ.elem)
        elif isinstance(typ, TArrow):
            for a in typ.args:
                collect_vars(a)
            collect_vars(typ.ret)
    collect_vars(t)
    var_map = {v: f"t{i+1}" for i, v in enumerate(vars_list)}

    def fmt(typ):
        typ = apply_subst(typ, {})
        if isinstance(typ, TVar):
            return var_map[typ]
        if isinstance(typ, TInt):
            return "Int"
        if isinstance(typ, TBool):
            return "Bool"
        if isinstance(typ, TString):
            return "Str"
        if isinstance(typ, TUnit):
            return "Unit"
        if isinstance(typ, TList):
            return f"List<{fmt(typ.elem)}>"
        if isinstance(typ, TRef):
            return f"Ref<{fmt(typ.elem)}>"
        if isinstance(typ, TArrow):
            args_str = ", ".join(fmt(a) for a in typ.args)
            ret_str = fmt(typ.ret)
            if len(typ.args) == 1:
                p = fmt(typ.args[0])
                if isinstance(typ.args[0], TArrow):
                    return f"({p}) -> {ret_str}"
                return f"{p} -> {ret_str}"
            else:
                return f"({args_str}) -> {ret_str}"
        return str(typ)
    return fmt(t)

