    # Iterative occurs check to prevent infinite recursion on malformed substitutions
    visited = set()
    stack = [t]
    while stack:
        curr = stack.pop()
        if isinstance(curr, TVar):
            # Apply substitution
            while curr in s:
                if curr in visited: break 
                visited.add(curr)
                curr = s[curr]
            if curr == v: return True
            continue
        if isinstance(curr, TList): stack.append(curr.e)
        elif isinstance(curr, TRef): stack.append(curr.e)
        elif isinstance(curr, TArrow):
            stack.extend(curr.args + (curr.ret,))
    return False

