        if len(term)!=3 or not isinstance(term[1], tuple) or not term[1]: raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not all(isinstance(p, str) and p for p in params): raise ValueError("Malformed fn params")
        if len(params) != len(set(params)): raise ValueError("Malformed fn params")
        new_env = {**env}
        ptypes = []
        for p in params:
            new_env[p] = fresh()
            ptypes.append(new_env[p])
        ret, s = infer(body, new_env, s)
        return TArrow(tuple(ptypes), ret), s
    elif tag == "call":
        if len(term)!=3 or not isinstance(term[2], tuple) or not term[2]: raise ValueError("Malformed call")
        f, args = term[1], term[2]
        ft, s = infer(f, env, s)

        # Create fresh types for arguments and return value
        arg_types = [fresh() for _ in args]
        ret_type = fresh()
        expected_ft = TArrow(tuple(arg_types), ret_type)

        # Unify function type with expected arrow type
        s = unify(ft, expected_ft, s)

        # Infer argument types and unify with expected argument types
        for i, a in enumerate(args):
            at, s = infer(a, env, s)
            s = unify(at, arg_types[i], s)

        return apply_subst(ret_type, s), s
    elif tag == "let":
        if len(term)!=4 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        t1, s = infer(e1, env, s)
        t1 = apply_subst(t1, s)
        if check_value(e1):
            t1 = generalize(t1, env, s)
        new_env = {**env, name: t1}
        return infer(e2, new_env, s)
    elif tag == "letrec":
        if len(term)!=4: raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(e1, tuple) or not e1 or e1[0] != "fn": raise ValueError("letrec requires fn")
        ntype = fresh()
        t1, s = infer(e1, {**env, name: ntype}, s)
        t1 = apply_subst(t1, s)
        if not isinstance(t1, TArrow): raise ValueError("letrec body must be function")
        s = unify(ntype, t1, s)
        ntype = apply_subst(ntype, s)
        ntype = generalize(ntype, env, s)
        new_env = {**env, name: ntype}
        return infer(e2, new_env, s)
    elif tag == "nil":
        if len(term)!=1: raise ValueError("Malformed nil")
        return TList(fresh()), s
    elif tag == "cons":
        if len(term)!=3: raise ValueError("Malformed cons")
        h, t = term[1], term[2]
        ht, s = infer(h, env, s)
        tt, s = infer(t, env, s)
        lt = TList(ht)
        s = unify(tt, lt, s)
        return apply_subst(lt, s), s
    elif tag == "match":
        if len(term)!=6: raise ValueError("Malformed match")
        s_term, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn: raise ValueError("Malformed match names")
        if hn == tn: raise ValueError("Match names must differ")
        st, s = infer(s_term, env, s)
        st = apply_subst(st, s)
        if not isinstance(st, TList): raise ValueError("Match requires List")
        elem = st.e
        new_env = {**env, hn: elem, tn: st}
        tn1, s = infer(e_nil, new_env, s)
        tn2, s = infer(e_cons, new_env, s)
        s = unify(tn1, tn2, s)
        return apply_subst(tn1, s), s
    elif tag == "ref":
        if len(term)!=2: raise ValueError("Malformed ref")
        et, s = infer(term[1], env, s)
        return TRef(et), s
    elif tag == "get":
        if len(term)!=2: raise ValueError("Malformed get")
        rt, s = infer(term[1], env, s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef): raise ValueError("Get requires Ref")
        return rt.e, s
    elif tag == "set":
        if len(term)!=3: raise ValueError("Malformed set")
        r, e = term[1], term[2]
        rt, s = infer(r, env, s)
        rt = apply_subst(rt, s)
        if not isinstance(rt, TRef): raise ValueError("Set requires Ref")
        et, s = infer(e, env, s)
        s = unify(et, rt.e, s)
        return TUnit, s
    else:
        raise ValueError("Unknown tag")

def print_type(t):
    vars_list = []
    def collect(typ):
        if isinstance(typ, TVar):
            if typ not in vars_list: vars_list.append(typ)
        elif isinstance(typ, TList): collect(typ.e)
        elif isinstance(typ, TRef): collect(typ.e)
        elif isinstance(typ, TArrow):
            for a in typ.args: collect(a)
            collect(typ.ret)
    collect(t)
    vm = {v: f"t{i+1}" for i, v in enumerate(vars_list)}

    def fmt(typ):
        if isinstance(typ, TVar): return vm[typ]
        if isinstance(typ, TInt): return "Int"
        if isinstance(typ, TBool): return "Bool"
        if isinstance(typ, TString): return "Str"
        if isinstance(typ, TUnit): return "Unit"
        if isinstance(typ, TList): return f"List<{fmt(typ.e)}>"
        if isinstance(typ, TRef): return f"Ref<{fmt(typ.e)}>"
        if isinstance(typ, TArrow):
            args_s = ", ".join(fmt(a) for a in typ.args)
            ret_s = fmt(typ.ret)
            if len(typ.args) == 1:
                p = fmt(typ.args[0])
                if isinstance(typ.args[0], TArrow): return f"({p}) -> {ret_s}"
                return f"{p} -> {ret_s}"
            return f"({args_s}) -> {ret_s}"
        return str(typ)
    return fmt(t)

def weak_infer(term):
    global _fresh
    _fresh = 0
    a = fresh()
    env = {
        "plus": TArrow((TInt, TInt), TInt),
        "eq": TScheme(set(), TArrow((a, a), TBool)),
        "size": TArrow((TString,), TInt)
    }
    try:
        res, _ = infer(term, env, {})
        return print_type(res)
    except ValueError:
        raise

import sys

sys.setrecursionlimit(10000)

class Type:
    pass

class TVar(Type):
    def __init__(self, id):
        self.id = id
        self.val = None

class TInt(Type):
    pass

class TBool(Type):
    pass

class TFunc(Type):
    def __init__(self, arg, ret):
        self.arg = arg
        self.ret = ret

class TList(Type):
    def __init__(self, elem):
        self.elem = elem

class TTuple(Type):
    def __init__(self, elems):
        self.elems = elems

_tv_counter = 0

def fresh():
    global _tv_counter
    t = TVar(_tv_counter)
    _tv_counter += 1
    return t

def get(t):
    while isinstance(t, TVar) and t.val is not None:
        t = t.val
    return t

def occurs(tv, t):
    t = get(t)
    if isinstance(t, TVar):
        return t is tv
    if isinstance(t, TFunc):
        return occurs(tv, t.arg) or occurs(tv, t.ret)
    if isinstance(t, TList):
        return occurs(tv, t.elem)
    if isinstance(t, TTuple):
        return any(occurs(tv, e) for e in t.elems)
    return False

def unify(t1, t2):
    t1, t2 = get(t1), get(t2)
    if isinstance(t1, TVar):
        if t1 is t2:
            return
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        t1.val = t2
        return
    if isinstance(t2, TVar):
        if occurs(t2, t1):
            raise ValueError("Infinite type")
        t2.val = t1
        return
    if type(t1) != type(t2):
        raise ValueError("Type mismatch")
    if isinstance(t1, TFunc):
        unify(t1.arg, t2.arg)
        unify(t1.ret, t2.ret)
    elif isinstance(t1, TList):
        unify(t1.elem, t2.elem)
    elif isinstance(t1, TTuple):
        if len(t1.elems) != len(t2.elems):
            raise ValueError("Tuple size mismatch")
        for e1, e2 in zip(t1.elems, t2.elems):
            unify(e1, e2)

def FV(T):
    if isinstance(T, TVar):
        return {T.id}
    if isinstance(T, TFunc):
        return FV(T.arg) | FV(T.ret)
    if isinstance(T, TList):
        return FV(T.elem)
    if isinstance(T, TTuple):
        res = set()
        for e in T.elems:
            res |= FV(e)
        return res
    return set()

def free_vars_env(env):
    res = set()
    for t, _ in env.values():
        res |= FV(t)
    return res

def instantiate(T, qvars):
    if isinstance(T, TVar):
        if T.id in qvars:
            return fresh()
        return T
    if isinstance(T, TFunc):
        return TFunc(instantiate(T.arg, qvars), instantiate(T.ret, qvars))
    if isinstance(T, TList):
        return TList(instantiate(T.elem, qvars))
    if isinstance(T, TTuple):
        return TTuple([instantiate(e, qvars) for e in T.elems])
    return T

def collect_vars(T, order):
    if isinstance(T, TVar):
        if T.id not in order:
            order.append(T.id)
    elif isinstance(T, TFunc):
        collect_vars(T.arg, order)
        collect_vars(T.ret, order)
    elif isinstance(T, TList):
        collect_vars(T.elem, order)
    elif isinstance(T, TTuple):
        for e in T.elems:
            collect_vars(e, order)

def idx_to_name(i):
    chars = []
    i += 1
    while i > 0:
        i, rem = divmod(i - 1, 26)
        chars.append(chr(ord('a') + rem))
    return ''.join(reversed(chars))

def type_to_str(T, mapping):
    if isinstance(T, TVar):
        return mapping[T.id]
    if isinstance(T, TInt):
        return "Int"
    if isinstance(T, TBool):
        return "Bool"
    if isinstance(T, TFunc):
        return f"({type_to_str(T.arg, mapping)} -> {type_to_str(T.ret, mapping)})"
    if isinstance(T, TList):
        return f"(List {type_to_str(T.elem, mapping)})"
    if isinstance(T, TTuple):
        if len(T.elems) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(type_to_str(e, mapping) for e in T.elems)})"
    return "?"

def lookup(name, env):
    T, qvars = env[name]
    return instantiate(T, qvars)

def infer(term, env):
    if isinstance(term, bool):
        raise ValueError("Malformed")
    if isinstance(term, int):
        return TInt()
    if term is True or term is False:
        return TBool()
    if isinstance(term, str):
        if not term:
            raise ValueError("Malformed")
        if term in env:
            return lookup(term, env)
        raise ValueError("Unbound variable")
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed")

    if tag == "lam":
        if len(term) != 3:
            raise ValueError("Malformed")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x:
            raise ValueError("Malformed")
        tv = fresh()
        new_env = {**env, x: (tv, set())}
        body_type = infer(body, new_env)
        return TFunc(tv, body_type)

    elif tag == "app":
        if len(term) != 3:
            raise ValueError("Malformed")
        f, a = term[1], term[2]
        f_type = infer(f, env)
        a_type = infer(a, env)
        if not isinstance(f_type, TFunc):
            raise ValueError("Type mismatch")
        unify(f_type.arg, a_type)
        return f_type.ret

    elif tag == "if":
        if len(term) != 4:
            raise ValueError("Malformed")
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env)
        unify(c_type, TBool())
        t_type = infer(t, env)
        e_type = infer(e, env)
        unify(t_type, e_type)
        return t_type

    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Malformed")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Malformed")
        e1_type = infer(e1, env)
        qvars = FV(e1_type) - free_vars_env(env)
        new_env = {**env, x: (e1_type, qvars)}
        return infer(e2, new_env)

    elif tag == "letrec":
        if len(term) != 3:
            raise ValueError("Malformed")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Malformed")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Malformed")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Malformed")
            names.append(n)
            exprs.append(e)
        if len(set(names)) != len(names):
            raise ValueError("Malformed")

        name_types = {}
        for n in names:
            name_types[n] = fresh()
        rec_env = {**env, **{n: (t, set()) for n, t in name_types.items()}}

        inferred = []
        for e in exprs:
            inferred.append(infer(e, rec_env))

        for n, inf in zip(names, inferred):
            unify(name_types[n], inf)

        final_env = {**env}
        for n in names:
            t = name_types[n]
            qvars = FV(t) - free_vars_env(env)
            final_env[n] = (t, qvars)

        return infer(body, final_env)

    elif tag == "tuple":
        elems = term[1:]
        n = len(elems)
        if n == 1:
            raise ValueError("Malformed")
        types = [infer(e, env) for e in elems]
        return TTuple(types)

    elif tag == "proj":
        if len(term) != 4:
            raise ValueError("Malformed")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool):
            raise ValueError("Malformed")
        if not isinstance(n, int) or isinstance(n, bool):
            raise ValueError("Malformed")
        if n < 2:
            raise ValueError("Malformed")
        if i < 0 or i >= n:
            raise ValueError("Malformed")
        e_type = infer(e, env)
        if not isinstance(e_type, TTuple):
            raise ValueError("Type mismatch")
        if len(e_type.elems) != n:
            raise ValueError("Type mismatch")
        return e_type.elems[i]

    else:
        raise ValueError("Malformed")

def group_type(term):
    global _tv_counter
    _tv_counter = 0

    # Initial environment with builtins
    env = {}

    # add: Int -> Int -> Int
    a = fresh()
    env["add"] = (TFunc(TInt(), TFunc(TInt(), TInt())), {a.id})

    # eq: a -> a -> Bool
    a = fresh()
    env["eq"] = (TFunc(TVar(a.id), TFunc(TVar(a.id), TBool())), {a.id})

    # nil: List a
    a = fresh()
    env["nil"] = (TList(TVar(a.id)), {a.id})

    # cons: a -> List a -> List a
    a = fresh()
    env["cons"] = (TFunc(TVar(a.id), TFunc(TList(TVar(a.id)), TList(TVar(a.id)))), {a.id})

    # head: List a -> a
    a = fresh()
    env["head"] = (TFunc(TList(TVar(a.id)), TVar(a.id)), {a.id})

    # tail: List a -> List a
    a = fresh()
    env["tail"] = (TFunc(TList(TVar(a.id)), TList(TVar(a.id))), {a.id})

    # isnil: List a -> Bool
    a = fresh()
    env["isnil"] = (TFunc(TList(TVar(a.id)), TBool()), {a.id})

    res_type = infer(term, env)

    order = []
    collect_vars(res_type, order)
    mapping = {idx: idx_to_name(idx) for idx in order}
    return type_to_str(res_type, mapping)

