    t1, t2 = resolve(t1), resolve(t2)
    if t1 is t2: return
    if isinstance(t1, TypeVarType):
        if occurs(t1, t2): raise ValueError("Infinite type")
        t1.link = t2
        return
    if isinstance(t2, TypeVarType):
        if occurs(t2, t1): raise ValueError("Infinite type")
        t2.link = t1
        return
    if not same_type(t1, t2): raise ValueError("Type mismatch")
    if isinstance(t1, ListType): unify(t1.elem, t2.elem)
    elif isinstance(t1, TupleType):
        if len(t1.elems) != len(t2.elems): raise ValueError("Tuple size mismatch")
        for a, b in zip(t1.elems, t2.elems): unify(a, b)
    elif isinstance(t1, FuncType):
