        return
    if not isinstance(term, tuple) or not term: raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed")
    if tag == "lam":
        if len(term) != 3: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
        validate(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed")
        validate(term[1]); validate(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed")
        validate(term[1]); validate(term[2]); validate(term[3])
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
        validate(term[2]); validate(term[3])
    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Malformed")
        group = term[1]
        if not isinstance(group, tuple) or not group: raise ValueError("Malformed")
        names = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed")
            n, e = item
            if not isinstance(n, str) or not n: raise ValueError("Malformed")
            if n in names: raise ValueError("Malformed")
            names.add(n)
            validate(e)
        validate(term[2])
    elif tag == "tuple":
        if len(term) == 2: raise ValueError("Tuple of size 1")
        for e in term[1:]: validate(e)
    elif tag == "proj":
        if len(term) != 4: raise ValueError("Malformed")
        i, n = term[1], term[2]
        if isinstance(i, bool) or isinstance(n, bool): raise ValueError("Malformed")
        if not isinstance(i, int) or not isinstance(n, int): raise ValueError("Malformed")
        if n < 2 or i < 0 or i >= n: raise ValueError("Malformed")
        validate(term[3])
    else:
        raise ValueError("Malformed")

def infer(term, env):
    if isinstance(term, bool): return BoolType()
    if isinstance(term, int): return IntType()
    if isinstance(term, str):
        for scope in reversed(env):
            if term in scope:
                return scope[term]
        raise ValueError("Unbound variable")

    tag = term[0]
    if tag == "lam":
        x, body = term[1], term[2]
        tv = fresh()
        new_env = env + [{x: tv}]
        res = infer(body, new_env)
        return FuncType(tv, res)

    elif tag == "app":
        f, a = term[1], term[2]
        ft = infer(f, env)
        at = infer(a, env)
        res_tv = fresh()
        unify(ft, FuncType(at, res_tv))
        return res_tv

    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        ct = infer(c, env)
        unify(ct, BoolType())
        tt = infer(t, env)
        et = infer(e, env)
        unify(tt, et)
        return tt

    elif tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        t1 = infer(e1, env)
        env_free = free_env(env)
        to_gen = free(t1) - env_free
        mapping = {v: fresh() for v in to_gen}
        t1_gen = substitute(t1, mapping)
        new_env = env + [{x: t1_gen}]
        return infer(e2, new_env)

    elif tag == "letrec":
        group, body = term[1], term[2]
        temp_env = env + {name: fresh() for name, _ in group}
        types = {}
        for name, expr in group:
            types[name] = infer(expr, temp_env)
        env_free = free_env(env)
        new_bindings = {}
        for name, _ in group:
            t = types[name]
            to_gen = free(t) - env_free
            mapping = {v: fresh() for v in to_gen}
            new_bindings[name] = substitute(t, mapping)
        final_env = env + new_bindings
        return infer(body, final_env)

    elif tag == "tuple":
        elems = term[1:]
        types = [infer(e, env) for e in elems]
        return TupleType(types)

    elif tag == "proj":
        i, n, e = term[1], term[2], term[3]
        et = infer(e, env)
        tuple_tv = TupleType([fresh() for _ in range(n)])
        unify(et, tuple_tv)
        return tuple_tv.elems[i]

    raise ValueError("Malformed")

def to_alpha(n):
    res = []
    n += 1
    while n > 0:
        n, rem = divmod(n - 1, 26)
        res.append(chr(ord('a') + rem))
    return ''.join(reversed(res))

def group_type(term):
    validate(term)
    t = infer(term, [])

    var_names = {}
    counter = [0]
    def get_name(v):
        if v.id not in var_names:
            var_names[v.id] = to_alpha(counter[0])
            counter[0] += 1
        return var_names[v.id]

    def assign_names(t):
        t = resolve(t)
        if isinstance(t, TypeVarType):
            get_name(t)
        elif isinstance(t, ListType):
            assign_names(t.elem)
        elif isinstance(t, TupleType):
            for e in t.elems: assign_names(e)
        elif isinstance(t, FuncType):
            assign_names(t.arg)
            assign_names(t.res)

    assign_names(t)

    def build(t):
        t = resolve(t)
        if isinstance(t, TypeVarType):
            return get_name(t)
        elif isinstance(t, IntType): return "Int"
        elif isinstance(t, BoolType): return "Bool"
        elif isinstance(t, ListType): return f"(List {build(t.elem)})"
        elif isinstance(t, TupleType):
            if not t.elems: return "(Tuple)"
            return f"(Tuple {' '.join(build(e) for e in t.elems)})"
        elif isinstance(t, FuncType): return f"({build(t.arg)} -> {build(t.res)})"
        return "Unknown"

    return build(t)

