class Type: pass

class IntType(Type): pass
class BoolType(Type): pass

class ListType(Type):
    def __init__(self, elem): self.elem = elem

class TupleType(Type):
    def __init__(self, elems): self.elems = list(elems)

class FuncType(Type):
    def __init__(self, arg, res): self.arg = arg; self.res = res

class TypeVarType(Type):
    def __init__(self, id):
        self.id = id
        self.link = None

_var_counter = 0

def fresh():
    global _var_counter
    v = TypeVarType(_var_counter)
    _var_counter += 1
    return v

def resolve(t):
    while isinstance(t, TypeVarType) and t.link is not None:
        t = t.link
    return t

def occurs(v, t):
    t = resolve(t)
    if isinstance(t, TypeVarType):
        return t is v
    if isinstance(t, ListType): return occurs(v, t.elem)
    if isinstance(t, TupleType): return any(occurs(v, e) for e in t.elems)
    if isinstance(t, FuncType): return occurs(v, t.arg) or occurs(v, t.res)
    return False

def unify(t1, t2):
    t1, t2 = resolve(t1), resolve(t2)
    if t1 is t2: return
    if isinstance(t1, TypeVarType):
        if occurs(t1, t2): raise ValueError("Infinite type")
        t1.link = t2
        return
    if isinstance(t2, TypeVarType):
        if occurs(t2, t1): raise ValueError("Infinite type")
        t2.link = t1
        return
    if not same_type(t1, t2): raise ValueError("Type mismatch")
    if isinstance(t1, ListType): unify(t1.elem, t2.elem)
    elif isinstance(t1, TupleType):
        if len(t1.elems) != len(t2.elems): raise ValueError("Tuple size mismatch")
        for a, b in zip(t1.elems, t2.elems): unify(a, b)
    elif isinstance(t1, FuncType):
        unify(t1.arg, t2.arg)
        unify(t1.res, t2.res)

def same_type(t1, t2):
    t1, t2 = resolve(t1), resolve(t2)
    if t1 is t2: return True
    if type(t1) != type(t2): return False
    if isinstance(t1, ListType): return same_type(t1.elem, t2.elem)
    if isinstance(t1, TupleType):
        if len(t1.elems) != len(t2.elems): return False
        return all(same_type(a, b) for a, b in zip(t1.elems, t2.elems))
    if isinstance(t1, FuncType):
        return same_type(t1.arg, t2.arg) and same_type(t1.res, t2.res)
    return True

def free(t):
    t = resolve(t)
    if isinstance(t, TypeVarType): return {t}
    if isinstance(t, ListType): return free(t.elem)
    if isinstance(t, TupleType): return set().union(*(free(e) for e in t.elems))
    if isinstance(t, FuncType): return free(t.arg) | free(t.res)
    return set()

def free_env(env):
    res = set()
    for scope in env:
        for t in scope.values():
            res |= free(t)
    return res

def substitute(t, mapping):
    t = resolve(t)
    if isinstance(t, TypeVarType):
        return mapping.get(t, t)
    if isinstance(t, ListType): return ListType(substitute(t.elem, mapping))
    if isinstance(t, TupleType): return TupleType([substitute(e, mapping) for e in t.elems])
    if isinstance(t, FuncType): return FuncType(substitute(t.arg, mapping), substitute(t.res, mapping))
    return t

def validate(term, in_group=False):
