            raise ValueError(f"Unknown tag: {tag}")

    try:
        res_type = infer(term, {})
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

    # Collect type vars in order of first appearance
    var_uids = _collect_vars_in_order(res_type)
    var_map = {uid: _name_for_uid(i+1) for i, uid in enumerate(var_uids)}

    return format_type(res_type, var_map)

