                t = infer(ex, rec_env)
                inferred_types[nm] = t

            final_rec_env = {**env}
            for nm in names:
                final_rec_env[nm] = inferred_types[nm]

            return infer(body, final_rec_env)

        elif tag == "tuple":
            n = len(term) - 1
            if n == 1:
                raise ValueError("tuple with n=1 is not allowed")
            if n == 0:
                return TupleType([])
            if n < 0:
                raise ValueError("tuple expects n >= 2 or n = 0")
            elems = [infer(e, env) for e in term[1:]]
            return TupleType(elems)

        elif tag == "proj":
            if len(term) != 4: raise ValueError("proj expects 4 args")
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or isinstance(n, bool): raise ValueError("i and n must be ints, not bools")
            if not isinstance(i, int) or not isinstance(n, int): raise ValueError("i and n must be ints")
            if n < 2: raise ValueError("proj n must be >= 2")
            if i < 0 or i >= n: raise ValueError("proj i out of bounds")
            t_e = infer(e, env)
            if not isinstance(t_e, TupleType): raise ValueError("proj target must be a tuple")
            if len(t_e.elems) != n: raise ValueError("proj tuple length mismatch")
            return t_e.elems[i]

        else:
            raise ValueError(f"Unknown tag: {tag}")

    try:
        res_type = infer(term, {})
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

    var_uids = _collect_vars_in_order(res_type)
    var_map = {uid: _name_for_uid(i+1) for i, uid in enumerate(var_uids)}

    return format_type(res_type, var_map)

import sys

sys.setrecursionlimit(100000)

_uid_counter = 0

def _fresh_uid():
    global _uid_counter
    _uid_counter += 1
    return _uid_counter

class TypeVar:
    __slots__ = ('uid', 'name')
    def __init__(self, uid):
        self.uid = uid
        self.name = None
    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.uid == other.uid
    def __hash__(self):
        return hash(self.uid)

class IntType: pass
class BoolType: pass

class ListType:
    __slots__ = ('elem',)
    def __init__(self, elem): self.elem = elem

class TupleType:
    __slots__ = ('elems',)
    def __init__(self, elems): self.elems = list(elems)

class ArrowType:
    __slots__ = ('arg', 'ret')
    def __init__(self, arg, ret):
        self.arg = arg
        self.ret = ret

def free_vars(t):
    if isinstance(t, TypeVar):
        return {t.uid}
    if isinstance(t, (IntType, BoolType)):
        return set()
    if isinstance(t, ListType):
        return free_vars(t.elem)
    if isinstance(t, TupleType):
        res = set()
        for e in t.elems:
            res |= free_vars(e)
        return res
    if isinstance(t, ArrowType):
        return free_vars(t.arg) | free_vars(t.ret)
    return set()

def apply_sub(sub, t):
    if isinstance(t, TypeVar):
        return sub.get(t.uid, t)
    if isinstance(t, ListType):
        return ListType(apply_sub(sub, t.elem))
    if isinstance(t, TupleType):
        return TupleType([apply_sub(sub, e) for e in t.elems])
    if isinstance(t, ArrowType):
        return ArrowType(apply_sub(sub, t.arg), apply_sub(sub, t.ret))
    return t

def compose_sub(s1, s2):
    res = {}
    for k, v in s1.items():
        res[k] = apply_sub(s2, v)
    res.update(s2)
    return res

def unify(t1, t2):
    sub = {}
    stack = [(t1, t2)]
    while stack:
        t1, t2 = stack.pop()
        while isinstance(t1, TypeVar) and t1.uid in sub: t1 = sub[t1.uid]
        while isinstance(t2, TypeVar) and t2.uid in sub: t2 = sub[t2.uid]

        if isinstance(t1, TypeVar) and isinstance(t2, TypeVar):
            if t1.uid != t2.uid:
                if t1.uid in free_vars(t2):
                    raise ValueError("Occurs check")
                sub[t1.uid] = t2
        elif isinstance(t1, TypeVar):
            if t1.uid in free_vars(t2):
                raise ValueError("Occurs check")
            sub[t1.uid] = t2
        elif isinstance(t2, TypeVar):
            if t2.uid in free_vars(t1):
                raise ValueError("Occurs check")
            sub[t2.uid] = t1
        elif isinstance(t1, ArrowType) and isinstance(t2, ArrowType):
            stack.append((t1.arg, t2.arg))
            stack.append((t1.ret, t2.ret))
        elif isinstance(t1, ListType) and isinstance(t2, ListType):
            stack.append((t1.elem, t2.elem))
        elif isinstance(t1, TupleType) and isinstance(t2, TupleType):
            if len(t1.elems) != len(t2.elems):
                raise ValueError("Tuple length mismatch")
            for e1, e2 in zip(t1.elems, t2.elems):
                stack.append((e1, e2))
        elif isinstance(t1, IntType) and isinstance(t2, IntType):
            pass
        elif isinstance(t1, BoolType) and isinstance(t2, BoolType):
            pass
        else:
            raise ValueError("Type mismatch")
    return sub

def _name_for_uid(n):
    res = []
    n -= 1
    while n >= 0:
        res.append(chr(ord('a') + n % 26))
        n = (n // 26) - 1
    return ''.join(reversed(res))

def format_type(t, var_map):
    if isinstance(t, TypeVar):
        return var_map[t.uid]
    if isinstance(t, IntType):
        return "Int"
    if isinstance(t, BoolType):
        return "Bool"
    if isinstance(t, ListType):
        return f"(List {format_type(t.elem, var_map)})"
    if isinstance(t, TupleType):
        if not t.elems:
            return "(Tuple)"
        return f"(Tuple {' '.join(format_type(e, var_map) for e in t.elems)})"
    if isinstance(t, ArrowType):
        return f"(-> {format_type(t.arg, var_map)} {format_type(t.ret, var_map)})"
    return str(t)

def _collect_vars_in_order(t):
    order = []
    seen = set()
    def traverse(t):
        if isinstance(t, TypeVar):
            if t.uid not in seen:
                seen.add(t.uid)
                order.append(t.uid)
        elif isinstance(t, ListType):
            traverse(t.elem)
        elif isinstance(t, TupleType):
            for e in t.elems:
                traverse(e)
        elif isinstance(t, ArrowType):
            traverse(t.arg)
            traverse(t.ret)
    traverse(t)
    return order

def instantiate(t):
    sub = {uid: TypeVar(_fresh_uid()) for uid in free_vars(t)}
    return apply_sub(sub, t)

def _INITIAL = {
    "add": ArrowType(IntType(), ArrowType(IntType(), IntType())),
    "eq": ArrowType(TypeVar(100), ArrowType(TypeVar(100), BoolType())),
    "nil": ListType(TypeVar(101)),
    "cons": ArrowType(TypeVar(102), ArrowType(ListType(TypeVar(102)), ListType(TypeVar(102)))),
    "head": ArrowType(ListType(TypeVar(103)), TypeVar(103)),
    "tail": ArrowType(ListType(TypeVar(104)), ListType(TypeVar(104))),
    "isnil": ArrowType(ListType(TypeVar(105)), BoolType()),
}
_INITIAL_NAMES = set(_INITIAL.keys())

def env_free_vars(env):
    res = set()
    for t in env.values():
        res |= free_vars(t)
    return res

def lookup(name, env):
    if name in _INITIAL_NAMES:
        return instantiate(_INITIAL[name])
    if name in env:
        return instantiate(env[name])
    raise ValueError(f"Unbound variable: {name}")

def infer(term, env):
    if isinstance(term, int) and not isinstance(term, bool):
        return (IntType(), {})
    if isinstance(term, bool):
        return (BoolType(), {})
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        t = env.get(term)
        if t is None:
            raise ValueError(f"Unbound variable: {term}")
        return (instantiate(t), {})

    if not isinstance(term, tuple):
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Non-string tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("lam expects 3 args")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x: raise ValueError("lam name must be non-empty str")
        tv = TypeVar(_fresh_uid())
        new_env = {**env, x: tv}
        t_body, sub_body = infer(body, new_env)
        return (ArrowType(tv, t_body), sub_body)

    elif tag == "app":
        if len(term) != 3: raise ValueError("app expects 3 args")
        f, a = term[1], term[2]
        t_f, sub_f = infer(f, env)
        t_a, sub_a = infer(a, env)
        sub = compose_sub(sub_f, sub_a)
        t_f = apply_sub(sub, t_f)
        t_a = apply_sub(sub, t_a)
        r = TypeVar(_fresh_uid())
        sub_unify = unify(t_f, ArrowType(t_a, r))
        sub = compose_sub(sub_unify, sub)
        return (apply_sub(sub, r), sub)

    elif tag == "if":
        if len(term) != 4: raise ValueError("if expects 4 args")
        c, t, e = term[1], term[2], term[3]
        t_c, sub_c = infer(c, env)
        t_t, sub_t = infer(t, env)
        t_e, sub_e = infer(e, env)
        sub = compose_sub(compose_sub(sub_c, sub_t), sub_e)
        t_c = apply_sub(sub, t_c)
        t_t = apply_sub(sub, t_t)
        t_e = apply_sub(sub, t_e)
        sub1 = unify(t_c, BoolType())
        t_t = apply_sub(sub1, t_t)
        t_e = apply_sub(sub1, t_e)
        sub2 = unify(t_t, t_e)
        sub = compose_sub(sub2, sub)
        return (apply_sub(sub, t_t), sub)

    elif tag == "let":
        if len(term) != 4: raise ValueError("let expects 4 args")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x: raise ValueError("let name must be non-empty str")
        t1, sub1 = infer(e1, env)
        new_env = {**env, x: t1}
        t2, sub2 = infer(e2, new_env)
        sub = compose_sub(sub1, sub2)
        return (apply_sub(sub, t2), sub)

    elif tag == "letrec":
        if len(term) != 3: raise ValueError("letrec expects 3 args")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or not group: raise ValueError("letrec group must be non-empty tuple")
        names = []
        exprs = []
        seen_names = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("letrec group items must be (name, expr) tuples")
            nm, ex = item
            if not isinstance(nm, str) or not nm: raise ValueError("letrec name must be non-empty str")
            if nm in seen_names: raise ValueError("Duplicate name in letrec group")
            seen_names.add(nm)
            names.append(nm)
            exprs.append(ex)

        rec_env = {**env}
        for nm in names:
            rec_env[nm] = TypeVar(_fresh_uid())

        inferred_types = {}
        all_subs = {}
        for nm, ex in zip(names, exprs):
            t, sub = infer(ex, rec_env)
            t = apply_sub(all_subs, t)
            all_subs = compose_sub(all_subs, sub)
            inferred_types[nm] = t

        for nm in names:
            inferred_types[nm] = apply_sub(all_subs, inferred_types[nm])

        env_free = env_free_vars(env)
        final_rec_env = {**env}
        for nm in names:
            final_rec_env[nm] = inferred_types[nm]

        t_body, sub_body = infer(body, final_rec_env)
        sub = compose_sub(all_subs, sub_body)
        return (apply_sub(sub, t_body), sub)

    elif tag == "tuple":
        n = len(term) - 1
        if n == 1:
            raise ValueError("tuple with n=1 is not allowed")
        if n == 0:
            return (TupleType([]), {})
        if n < 0:
            raise ValueError("tuple expects n >= 2 or n = 0")
        elems = []
        sub = {}
        for e in term[1:]:
            t, s = infer(e, env)
            t = apply_sub(sub, t)
            sub = compose_sub(sub, s)
            elems.append(t)
        return (TupleType(elems), sub)

    elif tag == "proj":
        if len(term) != 4: raise ValueError("proj expects 4 args")
        i, n, e = term[1], term[2], term[3]
        if isinstance(i, bool) or isinstance(n, bool): raise ValueError("i and n must be ints, not bools")
        if not isinstance(i, int) or not isinstance(n, int): raise ValueError("i and n must be ints")
        if n < 2: raise ValueError("proj n must be >= 2")
        if i < 0 or i >= n: raise ValueError("proj i out of bounds")
        t_e, sub_e = infer(e, env)
        t_e = apply_sub(sub_e, t_e)
        if not isinstance(t_e, TupleType): raise ValueError("proj target must be a tuple")
        if len(t_e.elems) != n: raise ValueError("proj tuple length mismatch")
        return (t_e.elems[i], sub_e)

    else:
        raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    global _uid_counter
    _uid_counter = 0

    try:
        res_type, sub = infer(term, {})
        res_type = apply_sub(sub, res_type)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

    var_uids = _collect_vars_in_order(res_type)
    var_map = {uid: _name_for_uid(i+1) for i, uid in enumerate(var_uids)}

    return format_type(res_type, var_map)

import sys
sys.setrecursionlimit(10000)

class Type:
    __slots__ = ('tag', 'args')
    def __init__(self, tag, *args):
        self.tag = tag
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.tag == other.tag and self.args == other.args
    def __hash__(self):
        return hash((self.tag, self.args))
    def __repr__(self):
        return f"Type({self.tag}, {self.args})"

def next_var_name(idx):
    res = []
    idx += 1
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        res.append(chr(ord('a') + rem))
    return ''.join(reversed(res))

def free_vars(t):
    if t.tag == 'Var':
        return {t.name}
    if t.tag == 'Tuple':
        return set().union(*(free_vars(a) for a in t.args))
    return set().union(*(free_vars(a) for a in t.args))

def free_env(env):
    return set().union(*(free_vars(t) for t in env.values()))

def apply_subst(t, subst):
    if t.tag == 'Var':
        return subst.get(t.name, t)
    if t.tag == 'Tuple':
        return Type('Tuple', *(apply_subst(a, subst) for a in t.args))
    return Type(t.tag, *(apply_subst(a, subst) for a in t.args))

def occurs_in(name, t, subst):
    t = apply_subst(t, subst)
    if t.tag == 'Var':
        return t.name == name
    if t.tag == 'Tuple':
        return any(occurs_in(name, a, {}) for a in t.args)
    return any(occurs_in(name, a, {}) for a in t.args)

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if t1 == t2:
        return subst
    if t1.tag == 'Var':
        if occurs_in(t1.name, t2, subst):
            raise ValueError("Infinite type")
        return {**subst, t1.name: t2}
    if t2.tag == 'Var':
        if occurs_in(t2.name, t1, subst):
            raise ValueError("Infinite type")
        return {**subst, t2.name: t1}
    if t1.tag == 'Arrow' and t2.tag == 'Arrow':
        subst = unify(t1.args[0], t2.args[0], subst)
        return unify(t1.args[1], t2.args[1], subst)
    if t1.tag == 'Tuple' and t2.tag == 'Tuple':
        if len(t1.args) != len(t2.args):
            raise ValueError("Tuple size mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            subst = unify(a1, a2, subst)
        return subst
    if t1.tag == 'List' and t2.tag == 'List':
        return unify(t1.args[0], t2.args[0], subst)
    raise ValueError("Type mismatch")

def instantiate(t, env_fv, fresh_counter):
    fv = free_vars(t)
    subst = {}
    for v in fv:
        if v not in env_fv:
            fresh_name = next_var_name(fresh_counter[0])
            fresh_counter[0] += 1
            subst[v] = Type('Var', fresh_name)
    return apply_subst(t, subst)

def format_type(t):
    if t.tag == 'Int':
        return 'Int'
    if t.tag == 'Bool':
        return 'Bool'
    if t.tag == 'Var':
        return t.name
    if t.tag == 'Arrow':
        return f"(-> {format_type(t.args[0])} {format_type(t.args[1])})"
    if t.tag == 'List':
        return f"(List {format_type(t.args[0])})"
    if t.tag == 'Tuple':
        if len(t.args) == 0:
            return "(Tuple)"
        return f"(Tuple {' '.join(format_type(a) for a in t.args)})"
    raise ValueError(f"Unknown type tag: {t.tag}")

def infer(term, env, fresh_counter, env_fv):
    if isinstance(term, int) and not isinstance(term, bool):
        return Type('Int')
    if term is True or term is False:
        return Type('Bool')
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty variable name")
        if term in env:
            return instantiate(env[term], env_fv, fresh_counter)
        raise ValueError(f"Unbound variable: {term}")
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Bad tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Bad lam")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x: raise ValueError("Bad param name")
        x_type = Type('Var', next_var_name(fresh_counter[0])); fresh_counter[0] += 1
        env_x = {**env, x: x_type}
        env_fv_x = env_fv | free_vars(x_type)
        body_type = infer(body, env_x, fresh_counter, env_fv_x)
        return Type('Arrow', x_type, body_type)

    elif tag == "app":
        if len(term) != 3: raise ValueError("Bad app")
        f, a = term[1], term[2]
        f_type = infer(f, env, fresh_counter, env_fv)
        a_type = infer(a, env, fresh_counter, env_fv)
        res_type = Type('Var', next_var_name(fresh_counter[0])); fresh_counter[0] += 1
        subst = unify(f_type, Type('Arrow', a_type, res_type), {})
        return apply_subst(res_type, subst)

    elif tag == "if":
        if len(term) != 4: raise ValueError("Bad if")
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env, fresh_counter, env_fv)
        unify(c_type, Type('Bool'), {})
        t_type = infer(t, env, fresh_counter, env_fv)
        e_type = infer(e, env, fresh_counter, env_fv)
        unify(t_type, e_type, {})
        return t_type

    elif tag == "let":
        if len(term) != 4: raise ValueError("Bad let")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x: raise ValueError("Bad let name")
        e1_type = infer(e1, env, fresh_counter, env_fv)
        env_x = {**env, x: e1_type}
        env_fv_x = env_fv | free_vars(e1_type)
        e2_type = infer(e2, env_x, fresh_counter, env_fv_x)
        return e2_type

    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Bad letrec")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Bad letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Bad letrec item")
            n, e = item
            if not isinstance(n, str) or not n: raise ValueError("Bad letrec name")
            if n in names: raise ValueError("Duplicate letrec name")
            names.append(n)
            exprs.append(e)
        temp_env = {**env}
        temp_env_fv = env_fv
        for n in names:
            temp_env[n] = Type('Var', next_var_name(fresh_counter[0])); fresh_counter[0] += 1
            temp_env_fv = temp_env_fv | {n}
        inferred_types = []
        for e in exprs:
            inferred_types.append(infer(e, temp_env, fresh_counter, temp_env_fv))
        env_rec = {**env}
        env_rec_fv = env_fv
        for n, t in zip(names, inferred_types):
            env_rec[n] = t
            # Do not add free vars of t to env_rec_fv to allow polymorphism in body
        return infer(body, env_rec, fresh_counter, env_rec_fv)

    elif tag == "tuple":
        if len(term) < 2: raise ValueError("Bad tuple")
        n = len(term) - 1
        if n == 1: raise ValueError("Tuple n=1 not allowed")
        types = []
        for i in range(1, len(term)):
            types.append(infer(term[i], env, fresh_counter, env_fv))
        return Type('Tuple', *types)

    elif tag == "proj":
        if len(term) != 4: raise ValueError("Bad proj")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Bad proj i")
        if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Bad proj n")
        if n < 2: raise ValueError("proj n < 2")
        if i < 0 or i >= n: raise ValueError("proj i out of bounds")
        e_type = infer(e, env, fresh_counter, env_fv)
        if e_type.tag != 'Tuple' or len(e_type.args) != n:
            raise ValueError("proj type mismatch")
        return e_type.args[i]

    else:
        raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    # Initial environment
    init_env = {
        "add": Type('Arrow', Type('Int'), Type('Arrow', Type('Int'), Type('Int'))),
        "eq": Type('Var', 'a'), # Will be instantiated properly
        "nil": Type('List', Type('Var', 'a')),
        "cons": Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a')))),
        "head": Type('Arrow', Type('List', Type('Var', 'a')), Type('Var', 'a')),
        "tail": Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a'))),
        "isnil": Type('Arrow', Type('List', Type('Var', 'a')), Type('Bool')),
    }
    # Actually, the spec says initial env has types like "a -> a -> Bool". 
    # We should store them with fresh vars or handle polymorphism.
    # To be safe, we'll store them as monomorphic but with fresh vars, 
    # and instantiate them on use. But they are globally polymorphic.
    # We'll store them as is, and instantiate will replace their vars.
    # But they share the same 'a'. We'll generate fresh vars for each binding.
    init_env = {
        "add": Type('Arrow', Type('Int'), Type('Arrow', Type('Int'), Type('Int'))),
        "eq": Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('Var', 'a'), Type('Bool'))),
        "nil": Type('List', Type('Var', 'a')),
        "cons": Type('Arrow', Type('Var', 'a'), Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a')))),
        "head": Type('Arrow', Type('List', Type('Var', 'a')), Type('Var', 'a')),
        "tail": Type('Arrow', Type('List', Type('Var', 'a')), Type('List', Type('Var', 'a'))),
        "isnil": Type('Arrow', Type('List', Type('Var', 'a')), Type('Bool')),
    }
    env_fv = free_env(init_env)
    fresh_counter = [0]
    # We need to instantiate init env vars on use. But they are already in env.
    # When we look up "eq", instantiate will replace 'a' with fresh. That's correct.
    # However, free_env(init_env) contains 'a'. So instantiate won't replace it if we check env_fv.
    # We want init env vars to be polymorphic. So we should NOT add them to env_fv.
    # Let's separate env and env_fv properly.
    # Actually, init_env should be treated as polymorphic. So env_fv should be empty initially.
    # But wait, if we pass env_fv={}, instantiate will replace all vars. That's correct for global polymorphism.

    res = infer(term, init_env, fresh_counter, set())
    return format_type(res)

