def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if t1 == t2:
        return subst
    if t1.tag == 'Var':
        if occurs_in(t1.args[0], t2, subst):
            raise ValueError("Infinite type")
        return {**subst, t1.args[0]: t2}
    if t2.tag == 'Var':
        if occurs_in(t2.args[0], t1, subst):
            raise ValueError("Infinite type")
        return {**subst, t2.args[0]: t1}
