import sys
from collections import deque

def branch_influence(n, edges, entry, exits, targets):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2):
            raise ValueError("edges must be a list of pairs")
        if not (isinstance(e[0], int) and isinstance(e[1], int)) or isinstance(e[0], bool) or isinstance(e[1], bool):
            raise ValueError("edges must be a list of pairs of ints")
        if not (0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    for s in (exits, targets):
        if not isinstance(s, (list, tuple, set)):
            raise ValueError("exits and targets must each be a list, tuple or set")
        for x in s:
            if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
                raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # 1. Reachable from entry
    R = set()
    q = deque([entry])
    R.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # 2. Filter graph to R
    adj_R = [[] for _ in range(n)]
    for u in R:
        for v in adj[u]:
            if v in R:
                adj_R[u].append(v)

    # Add virtual END node (index n)
    END = n
    adj_A = [[] for _ in range(n + 1)]
    for u in R:
        for v in adj_R[u]:
            adj_A[u].append(v)
        if u in exits:
            adj_A[u].append(END)

    # 3. Find A: nodes in R from which END is reachable
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in adj_A[u]:
            rev_adj[v].append(u)

    A_set = set()
    q = deque([END])
    A_set.add(END)
    while q:
        u = q.popleft()
        for v in rev_adj[u]:
            if v not in A_set:
                A_set.add(v)
                q.append(v)

    # Filter to A_set + END
    final_adj = [[] for _ in range(n + 1)]
    for u in A_set:
        for v in adj_A[u]:
            if v in A_set:
                final_adj[u].append(v)

    # 4. Compute post-dominators (idom)
    # idom[v] is the immediate post-dominator of v
    idom = {END: END}
    for v in A_set:
        if v != END:
            idom[v] = None

    def intersect(u, v):
        while u != v:
            while u != idom[u]:
                u = idom[u]
            while v != idom[v]:
                v = idom[v]
            u = idom[u]
            v = idom[v]
        return u

    changed = True
    while changed:
        changed = False
        for v in A_set:
            if v == END: continue
            succs = [s for s in final_adj[v] if s in idom]
            if not succs:
                continue
            if len(succs) == 1:
                new_idom = succs[0]
            else:
                new_idom = succs[0]
                for s in succs[1:]:
                    new_idom = intersect(new_idom, s)
            if idom[v] != new_idom:
                idom[v] = new_idom
                changed = True

    # 5. Build PD tree and compute tin/tout for ancestry checks
    pd_children = [[] for _ in range(n + 1)]
    for v in A_set:
        if v != END:
            p = idom[v]
            pd_children[p].append(v)

    tin = [0] * (n + 1)
    tout = [0] * (n + 1)
    timer = 0
    stack = [END]
    while stack:
        u = stack.pop()
        if u >= 0:
            tin[u] = timer
            timer += 1
            stack.append(~u)
            for v in pd_children[u]:
                stack.append(v)
        else:
            u = ~u
            tout[u] = timer

    def is_ancestor(u, v):
        return tin[u] <= tin[v] and tout[u] >= tout[v]

    # 6. Build control dependence graph (reverse: control_sources[y] contains x if y is control dependent on x)
    control_sources = {v: set() for v in A_set}
    for x in A_set:
        if x == END: continue
        for s in final_adj[x]:
            if s == END: continue
            curr = s
            while True:
                if curr == END:
                    break
                if is_ancestor(curr, x):
                    if curr == x:
                        control_sources[x].add(x)
                    break
                control_sources[curr].add(x)
                curr = idom[curr]

    # 7. Compute C: smallest set containing T ∩ A such that if y in C ∪ T and y is control dependent on x, then x in C
    T_in_A = set(targets) & A_set
    C = set(T_in_A)
    q = deque(T_in_A)
    while q:
        y = q.popleft()
        for x in control_sources[y]:
            if x not in C:
                C.add(x)
                q.append(x)

    targets_not_in_A = sorted(targets - A_set)
    return (sorted(C), targets_not_in_A)

