        if not isinstance(s, (list, tuple, set)):
            raise ValueError("exits and targets must each be a list, tuple or set")
        for x in s:
            if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
                raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # 1. Reachable from entry
    R = set()
    q = deque([entry])
    R.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # 2. Filter graph to R
    adj_R = [[] for _ in range(n)]
    for u in R:
        for v in adj[u]:
            if v in R:
                adj_R[u].append(v)

    # Add virtual END node (index n)
    END = n
    adj_A = [[] for _ in range(n + 1)]
    for u in R:
        for v in adj_R[u]:
            adj_A[u].append(v)
        if u in exits:
            adj_A[u].append(END)

    # 3. Find A: nodes in R from which END is reachable
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in adj_A[u]:
            rev_adj[v].append(u)

    A_set = set()
    q = deque([END])
    A_set.add(END)
    while q:
        u = q.popleft()
        for v in rev_adj[u]:
            if v not in A_set:
                A_set.add(v)
                q.append(v)

    # Filter to A_set + END
    final_adj = [[] for _ in range(n + 1)]
    for u in A_set:
        for v in adj_A[u]:
            if v in A_set:
                final_adj[u].append(v)

    # 4. Compute post-dominators (idom)
    # idom[v] is the immediate post-dominator of v
    # Initialize idom[v] = v for all v in A, idom[END] = END
    idom = {v: v for v in A_set}

    def intersect(u, v):
        while u != v:
            while u != idom[u]:
                u = idom[u]
            while v != idom[v]:
                v = idom[v]
            u = idom[u]
            v = idom[v]
        return u

    changed = True
