    # But we can just iterate.

    # To ensure convergence, we can use a worklist algorithm
    worklist = deque(nodes_list)

    # Initial pass: compute idom based on current idom values
    # Since idom[v] starts as v, this might not change much initially.
    # But for nodes with direct edge to END, idom becomes END.

    # Let's do a BFS from END in reverse graph to get layers?
    # Actually, the standard iterative algorithm works fine.

    while worklist:
        u = worklist.popleft()
        succs = [s for s in final_adj[u] if s in idom]
        if not succs:
            continue

        if len(succs) == 1:
            new_idom = idom[succs[0]]
        else:
            new_idom = idom[succs[0]]
            for s in succs[1:]:
                new_idom = intersect(new_idom, idom[s])

        if idom[u] != new_idom:
            idom[u] = new_idom
            # Add u to worklist? No, u's idom changed, so its predecessors might need update.
            # But we are computing post-dominators, so predecessors in original graph (successors in reverse)
            # depend on u.
            # In original graph, if idom[u] changes, then idom[p] for p->u might change.
            # So we need to re-evaluate predecessors of u.
            # Predecessors of u in original graph are nodes v such that u in final_adj[v].
            # We can precompute reverse adjacency for this.
            pass

    # Actually, the worklist should contain nodes whose idom changed, and we need to update their predecessors.
    # Let's rebuild the logic properly.

    # Re-initialize
    idom = {v: v for v in A_set}
    idom[END] = END

    # Precompute predecessors in the filtered graph (for post-dominator updates)
    # In original graph, edge v -> u. u is successor of v.
    # idom[v] depends on idom[u].
    # So if idom[u] changes, we might need to update idom[v].
    # So we need reverse adjacency of final_adj (which is adj in reverse graph).
    # But final_adj is already built. We can build rev_final_adj.

    rev_final_adj = [[] for _ in range(n + 1)]
    for u in A_set:
        for v in final_adj[u]:
            rev_final_adj[v].append(u)

    worklist = deque(nodes_list)
    # Mark all as needing update?
    # Actually, we can start with all nodes in worklist.

    while worklist:
        u = worklist.popleft()
        if u == END: continue

        succs = [s for s in final_adj[u] if s in idom]
        if not succs:
            continue

        if len(succs) == 1:
            new_idom = idom[succs[0]]
        else:
            new_idom = idom[succs[0]]
            for s in succs[1:]:
                new_idom = intersect(new_idom, idom[s])

        if idom[u] != new_idom:
            idom[u] = new_idom
            # Add predecessors to worklist
            for p in rev_final_adj[u]:
                if p in idom and p not in worklist: # Check if already in worklist to avoid duplicates
                     worklist.append(p)

    # 5. Build PD tree and compute tin/tout for ancestry checks
    pd_children = [[] for _ in range(n + 1)]
    for v in A_set:
        if v != END:
            p = idom[v]
            pd_children[p].append(v)

    tin = [0] * (n + 1)
    tout = [0] * (n + 1)
    timer = 0
    stack = [END]
    while stack:
        u = stack.pop()
        if u >= 0:
            tin[u] = timer
            timer += 1
            stack.append(~u)
            for v in pd_children[u]:
                stack.append(v)
        else:
            u = ~u
            tout[u] = timer

    def is_ancestor(u, v):
        return tin[u] <= tin[v] and tout[u] >= tout[v]

    # 6. Build control dependence graph
    # y is control dependent on x if exists edge x -> s in A such that y post-dominates s and y does not strictly post-dominate x.
    # We need to find for each x, the set of y's that are control dependent on x.
    # Or rather, for each y, who controls it.
    # But we need to find C, so we can build a reverse graph: control_sources[y] = {x | y is control dependent on x}

    control_sources = {v: set() for v in A_set}

    # Iterate over all edges x -> s in A
    for x in A_set:
        if x == END: continue
        for s in final_adj[x]:
            if s == END: continue
            # y must post-dominate s. The set of such y's are ancestors of s in PD tree (including s).
            # But we need to check condition for each y.
            # Instead of iterating all y, we can iterate y on the path from s to root in PD tree.
            curr = s
            while True:
                # curr is an ancestor of s in PD tree, so curr post-dominates s.
                # Check if curr strictly post-dominates x.
                # Strictly post-dominates means curr is proper ancestor of x in PD tree.
                # i.e., curr != x and is_ancestor(curr, x).
                if curr == x:
                    # curr does not strictly post-dominate x (since curr == x)
                    # So x controls curr.
                    control_sources[curr].add(x)
                else:
                    if is_ancestor(curr, x):
                        # curr strictly post-dominates x, so x does not control curr.
                        # Also, any node above curr (closer to END) also strictly post-dominates x.
                        # So we can stop.
                        break
                    else:
                        # curr does not strictly post-dominate x.
                        # So x controls curr.
                        control_sources[curr].add(x)

                # Move up in PD tree
                if curr == END:
                    break
                curr = idom[curr]

    # 7. Compute C
    T_in_A = set(targets) & A_set
    C = set(T_in_A)
    q = deque(T_in_A)
    while q:
        y = q.popleft()
        for x in control_sources[y]:
            if x not in C:
                C.add(x)
                q.append(x)

    targets_not_in_A = sorted(targets - A_set)
    return (sorted(C), targets_not_in_A)

