    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Compute R: nodes reachable from entry
    reachable = [False] * n
    q = deque([entry])
    reachable[entry] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # Compute A: nodes in R that can reach an exit
    in_A = [False] * n
    q = deque()
    for x in exits:
        if reachable[x]:
            in_A[x] = True
            q.append(x)
    while q:
        u = q.popleft()
        for v in rev_adj[u]:
            if reachable[v] and not in_A[v]:
                in_A[v] = True
                q.append(v)

    # Filter graph to A
    f_adj = [[] for _ in range(n)]
    rev_f_adj = [[] for _ in range(n + 1)]
    for u in range(n):
        if not in_A[u]:
