    # dom_mask[u] is a bitmask of all nodes that post-dominate u (including u)
    full_mask = (1 << (n + 1)) - 1
    dom_mask = [full_mask] * (n + 1)
    dom_mask[n] = 1 << n

    changed = True
    while changed:
        changed = False
        for u in range(n):
            if not in_A[u]:
                continue
            preds = rev_f_adj[u]
            if not preds:
                new_mask = 1 << n
            else:
                new_mask = dom_mask[preds[0]]
                for p in preds[1:]:
                    new_mask &= dom_mask[p]
                new_mask |= (1 << u)
            if new_mask != dom_mask[u]:
                dom_mask[u] = new_mask
                changed = True

    # Compute immediate post-dominators (ipd)
    # ipd[u] is the node v != u in dom_mask[u] with the smallest popcount
    ipd = [n] * n
    for u in range(n):
        if not in_A[u]:
            continue
        mask = dom_mask[u]
        best = n
        best_count = float('inf')
        temp = mask
        while temp:
            lsb = temp & -temp
            v = lsb.bit_length() - 1
            temp ^= lsb
            if v == u:
                continue
            cnt = dom_mask[v].bit_count()
            if cnt < best_count:
                best_count = cnt
                best = v
        ipd[u] = best

    # Compute C using BFS on control dependence
    T_set = set(targets)
    T_in_A = [t for t in T_set if in_A[t]]

    C = set()
    queue = deque(T_in_A)
    for t in T_in_A:
        C.add(t)

    while queue:
        y = queue.popleft()
        for s in f_adj[y]:
            curr = s
            while curr != n and curr != y:
                if curr not in C:
                    C.add(curr)
                    queue.append(curr)
                curr = ipd[curr]
            # y itself is control dependent on y if it has successors, 
            # but we already added y when it entered the queue.

    targets_not_in_A = sorted([t for t in targets if not in_A[t]])
    C_sorted = sorted(C)

    return (C_sorted, targets_not_in_A)

