        if not (isinstance(e, int) and not isinstance(e, bool) and 0 <= e < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not (isinstance(t, int) and not isinstance(t, bool) and 0 <= t < n):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # Build adjacency lists
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # R: reachable from entry
    reachable = [False] * n
    stack = [entry]
    reachable[entry] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                stack.append(v)

    # A: nodes in R that can reach END (virtual node n)
    rev_adj_for_end = [[] for _ in range(n + 1)]
    for u in range(n):
        if reachable[u]:
            for v in adj[u]:
                if reachable[v]:
                    rev_adj_for_end[v].append(u)
    for e in exits:
        if reachable[e]:
            rev_adj_for_end[n].append(e)

    can_reach_end = [False] * (n + 1)
    can_reach_end[n] = True
    stack = [n]
    while stack:
        u = stack.pop()
        for v in rev_adj_for_end[u]:
            if not can_reach_end[v]:
                can_reach_end[v] = True
                stack.append(v)

    A = {u for u in range(n) if reachable[u] and can_reach_end[u]}
    if not A:
        return ([], sorted(targets))

    # Nodes for post-dominator tree: A ∪ {END}
    dom_nodes_list = [n] + sorted(A)
    node_to_idx = {node: i for i, node in enumerate(dom_nodes_list)}

    # Build DFS tree from END in the reversed graph restricted to A ∪ {END}
    num = [-1] * (n + 1)
    parent_num = [-1] * (n + 1)
    order = []

    # Pre-filter children for efficiency
    children = [[] for _ in range(len(dom_nodes_list))]
    for i, u in enumerate(dom_nodes_list):
        for v in rev_adj_for_end[u]:
            if v in node_to_idx:
                children[i].append(node_to_idx[v])

    stack = [0]
    num[n] = 0
    parent_num[n] = -1
    while stack:
        u = stack.pop()
        order.append(u)
        for v in children[u]:
            if num[v] == -1:
                num[v] = len(order)
                parent_num[v] = num[u]
                stack.append(v)

    k = len(order)
    dom_nodes = order  # dom_nodes[i] is the node with num == i

    # Lengauer-Tarjan for post-dominators
    semi = list(range(k))
    idom = list(range(k))
    best = list(range(k))
    ancestor = [-1] * k

    def find(v):
        if ancestor[v] == v:
            return v
        res = find(ancestor[v])
        if semi[best[ancestor[v]]] < semi[best[v]]:
            best[v] = best[ancestor[v]]
        ancestor[v] = res
        return res

    def link(u, v):
        ancestor[v] = u
        if semi[best[v]] < semi[best[u]]:
            best[u] = best[v]

    buckets = [[] for _ in range(k)]

    for i in range(k - 1, 0, -1):
        v = order[i]
        preds = children[v]
        for u in preds:
            if num[u] == -1:
                continue
            w = find(u)
            if semi[w] < semi[v]:
                semi[v] = semi[w]
        link(parent_num[v], v)
        buckets[semi[v]].append(v)

    for i in range(1, k):
        v = order[i]
        w = parent_num[v]
        for b in buckets[semi[v]]:
            z = find(b)
            if semi[z] < semi[b]:
                idom[b] = z
            else:
                idom[b] = w
        buckets[semi[v]].clear()

    for i in range(1, k):
        v = order[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # Compute C using BFS on control dependence
    C = set()
    queue = []
    for t in targets:
        if t in A:
            idx = node_to_idx[t]
            if idx not in C:
                C.add(idx)
                queue.append(idx)

    head = 0
    while head < len(queue):
        x = queue[head]
        head += 1
        x_node = dom_nodes[x]
        for s in adj[x_node]:
            if s not in A:
                continue
            idx_s = node_to_idx[s]
            y = idom[idx_s]
            while y != 0 and y != x:
                if y not in C:
                    C.add(y)
                    queue.append(y)
                y = idom[y]

    targets_not_in_A = sorted([t for t in targets if t not in A])
    C_nodes = sorted([dom_nodes[i] for i in C])

    return (C_nodes, targets_not_in_A)

