    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = set()
    stack = [entry]
    while stack:
        u = stack.pop()
        if u in reachable:
            continue
        reachable.add(u)
        stack.extend(adj[u])

