    dfs_num = [-1] * n
    dfs_rev = [0] * n
    parent = [entry] * n
    semi = list(range(n))
    idom = list(range(n))
    ancestor = list(range(n))
    bucket = [[] for _ in range(n)]
    val = list(range(n))
    label = list(range(n))

