    while stack:
        u = stack.pop()
        if dfs_num[u] != -1:
            continue
        dfs_num[u] = dfn
        dfn += 1
        dfs_rev[dfn-1] = u
        for v in adj[u]:
            if dfs_num[v] == -1:
                parent[v] = u
                stack.append(v)
            elif dfs_num[v] < dfs_num[u]:
