            for y in df[d]:
                if y not in P_x:
                    P_x.add(y)
                    queue.append(y)

        if not P_x:
            continue

        # Liveness analysis for x
        has_def_upd = [False] * n
        has_use_exposed = [False] * n

        for u in reachable:
            if u not in blocks:
                continue
            seen_def = False
            for op, name in blocks[u]:
                if name == x:
                    if op in ("def", "upd"):
                        seen_def = True
                        has_def_upd[u] = True
                    elif op == "use" and not seen_def:
                        has_use_exposed[u] = True

        live_in = [False] * n
        worklist = []
        for u in reachable:
            if has_use_exposed[u]:
                live_in[u] = True
                worklist.append(u)

        wl_idx = 0
        while wl_idx < len(worklist):
            z = worklist[wl_idx]
            wl_idx += 1
            for p in pred[z]:
                if not has_def_upd[p] and not live_in[p]:
                    live_in[p] = True
                    worklist.append(p)

        # Combine
        phis_for_node = {}
        for u in reachable:
            if u in P_x and live_in[u]:
                phis_for_node[u] = phis_for_node.get(u, 0) + 1

        for u in sorted(phis_for_node.keys()):
            if u not in results or results[-1][0] != u:
                results.append([u, []])
            results[-1][1].append(x)

    # Format output
    return [(u, sorted(names)) for u, names in results]

