        if parent[w] != w:
            link(parent[w], w)
            for v in bucket[parent[w]]:
                z = eval(v)
                if semi[z] < semi[w]:
                    idom[v] = z
                else:
                    idom[v] = s

    for i in range(1, len(dfs_order)):
        w = dfs_order[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

