        if not D_x:
            continue

        # P(x) = closure under DF
        P_x = set(D_x)
        queue = list(D_x)
        while queue:
            d = queue.pop()
            for y in df[d]:
                if y not in P_x:
                    P_x.add(y)
                    queue.append(y)

        if not P_x:
            continue

        # Liveness analysis for x
        has_def_upd = [False] * n
        has_use_exposed = [False] * n

        for u in reachable:
            if u not in blocks:
                continue
            seen_def = False
            for op, name in blocks[u]:
                if name == x:
                    if op in ("def", "upd"):
                        seen_def = True
                        has_def_upd[u] = True
                    elif op == "use" and not seen_def:
                        has_use_exposed[u] = True

        live_in = [False] * n
        live_out = [False] * n
        worklist = []

        for u in reachable:
            if has_use_exposed[u]:
                live_in[u] = True
                worklist.append(u)

        while worklist:
            u = worklist.pop()
            for p in pred[u]:
