    parent = [-1] * n

    stack = [entry]
    dfn[entry] = 0
    dfs_order.append(entry)
    while stack:
        u = stack[-1]
        pushed = False
        for v in adj[u]:
            if dfn[v] == -1:
                dfn[v] = len(dfs_order)
                parent[v] = u
                dfs_order.append(v)
                stack.append(v)
                pushed = True
                break
        if not pushed:
            stack.pop()

    semi = list(range(n))
    ancestor = list(range(n))
    idom = [-1] * n
    bucket = [[] for _ in range(n)]
    uf = list(range(n))

    def find(v):
        if uf[v] == v:
            return v
        root = find(uf[v])
        if semi[ancestor[uf[v]]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[uf[v]]
        uf[v] = root
        return root

    def link(u, v):
        uf[v] = u
        if semi[ancestor[u]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[u]

    # Semi-dominators
    for v in reversed(dfs_order)[1:]:
        for u in pred[v]:
            if dfn[u] != -1:
                if dfn[u] < semi[v]:
                    semi[v] = dfn[u]
            else:
                if semi[find(u)] < semi[v]:
                    semi[v] = semi[find(u)]

    # Dominators
    for v in dfs_order[1:]:
        p = parent[v]
        link(p, v)
        for w in bucket[p]:
            wsemi = semi[find(w)]
            if wsemi < semi[w]:
                idom[w] = find(w)
            else:
                idom[w] = p

    # Fix dominators
    for v in dfs_order[1:]:
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # Dominance Frontier
    df_adj = [set() for _ in range(n)]
    for v in dfs_order[1:]:
        p = idom[v]
        w = v
        while w != p:
            df_adj[p].add(v)
            w = idom[w]

    # Collect all names
    all_names = set(params)
    for instr_list in reachable_blocks.values():
        for _, name in instr_list:
            all_names.add(name)

    phi_by_node = {}

    for x in all_names:
        # D(x)
        D_x = set()
        Use_x = set()
        Def_x = set()

        for node, instrs in reachable_blocks.items():
            seen_def = False
            for op, name in instrs:
                if op in ('def', 'upd'):
                    seen_def = True
                    Def_x.add(node)
                if op == 'use' and not seen_def:
                    Use_x.add(node)
                if op == 'upd' and not seen_def:
                    Use_x.add(node)

        if x in params:
            D_x.add(entry)
        # Add defs/upds for x
        for node in Def_x:
            # Check if x is actually defined here
            for op, name in reachable_blocks[node]:
                if name == x and op in ('def', 'upd'):
                    D_x.add(node)
                    break

        # P(x) via BFS on DF graph
        P_x = set(D_x)
        q = deque(P_x)
        visited_P = set(P_x)
        while q:
            u = q.popleft()
            for v in df_adj[u]:
                if v not in visited_P:
                    visited_P.add(v)
                    q.append(v)
        P_x = visited_P

        # Liveness via BFS on reverse graph
        live_x = set()
        q = deque(Use_x)
        visited_L = set(Use_x)
        while q:
            u = q.popleft()
            for v in rev_adj[u]:
                if v not in visited_L and v not in Def_x:
                    visited_L.add(v)
                    q.append(v)
        live_x = visited_L

        # Intersection
        phi_nodes = P_x & live_x
        if phi_nodes:
            if x not in phi_by_node:
                phi_by_node[x] = set()
            phi_by_node[x].update(phi_nodes)

    # Format output
    result = []
    node_phis = {}
    for x, nodes in phi_by_node.items():
        for node in nodes:
            if node not in node_phis:
                node_phis[node] = []
            node_phis[node].append(x)

    for node in sorted(node_phis.keys()):
        result.append((node, sorted(node_phis[node])))

    return result

