    reachable_blocks = {u: blocks[u] for u in reachable if u in blocks}

    # Build pred for reachable nodes
    pred = [[] for _ in range(n)]
    for u in reachable:
        for v in adj[u]:
            if v in reachable:
                pred[v].append(u)

    # Lengauer-Tarjan Dominators
    dfn = [-1] * n
    dfs_order = []
    parent = [-1] * n

    stack = [entry]
    dfn[entry] = 0
    dfs_order.append(entry)
    while stack:
        u = stack[-1]
        pushed = False
        for v in adj[u]:
            if dfn[v] == -1:
