                break
        if not pushed:
            stack.pop()

    semi = list(range(n))
    ancestor = list(range(n))
    idom = [-1] * n
    bucket = [[] for _ in range(n)]
    uf = list(range(n))

    def find(v):
        if uf[v] == v:
            return v
        root = find(uf[v])
        if semi[ancestor[uf[v]]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[uf[v]]
        uf[v] = root
        return root

    def link(u, v):
        uf[v] = u
        if semi[ancestor[u]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[u]

    # Semi-dominators
    # Iterate in reverse DFS order (excluding entry)
    for i in range(len(dfs_order) - 1, 0, -1):
        v = dfs_order[i]
        for u in pred[v]:
            if dfn[u] != -1:
                if dfn[u] < semi[v]:
                    semi[v] = dfn[u]
            else:
                if semi[find(u)] < semi[v]:
                    semi[v] = semi[find(u)]

