    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        p = parent[v]
        link(p, v)
        for w in bucket[p]:
            wsemi = semi[find(w)]
            if wsemi < semi[w]:
                idom[w] = find(w)
            else:
                idom[w] = p

    # Fix dominators
    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

