    df_adj = [set() for _ in range(n)]
    for v in dfs_order[1:]:
        p = idom[v]
        w = v
        while w != p:
            df_adj[p].add(v)
            w = idom[w]

    # Collect all names
    all_names = set(params)
    for instr_list in reachable_blocks.values():
        for _, name in instr_list:
            all_names.add(name)

    phi_by_node = {}

    for x in all_names:
        # D(x)
        D_x = set()
        Use_x = set()
        Def_x = set()

        for node, instrs in reachable_blocks.items():
            seen_def = False
            for op, name in instrs:
                if name == x:
                    if op in ('def', 'upd'):
                        seen_def = True
                        Def_x.add(node)
                    if op == 'use' and not seen_def:
                        Use_x.add(node)
                    if op == 'upd' and not seen_def:
                        Use_x.add(node)

        if x in params:
            D_x.add(entry)

        # P(x) via BFS on DF graph
        P_x = set(D_x)
        q = deque(P_x)
        visited_P = set(P_x)
        while q:
            u = q.popleft()
            for v in df_adj[u]:
                if v not in visited_P:
                    visited_P.add(v)
                    q.append(v)
        P_x = visited_P

        # Liveness via BFS on reverse graph
        # Liveness logic:
        # 1. Identify Def_x nodes (nodes defining x).
        #    Note: Param definition at entry does not affect liveness.
        #    So if x in params, entry should not block liveness propagation?
        #    Actually, entry is in D_x for phi calculation, but for liveness,
        #    "implicit assignment of a param does not affect liveness".
        #    This means entry does not kill the value for liveness purposes.
        #    However, if entry is in Def_x (because x is param), we should ignore it for blocking?
        #    Let's check example 2: entry 0, x='a' in params.
        #    Def_x would contain 0.
        #    If 0 blocks liveness, then 'a' wouldn't be live-in at 0 (unless 0 uses it).
        #    0 uses 'a'. So 'a' is live-in.
        #    But if 0 blocks propagation from pred, it might matter.
        #    Here entry has no preds in reachable subgraph? No, 1->0.
        #    If 0 blocks, then 'a' not live-in at 1.
        #    But 'a' is param, so it's available at entry.
        #    Wait, liveness is about "is x available at entry of block".
        #    If x is param, it is available at entry.
        #    So liveness should propagate backwards from entry?
        #    No, liveness is defined as path to use.
        #    If x is param, it is defined at entry.
        #    If there is a use at entry (upward exposed), x is live-in at entry.
        #    If there is a use at node w reachable from entry, and path from entry to w has no defs,
        #    then x is live-in at entry.
        #    Since entry is the start, path is just entry...
        #    Wait, if x is param, it's defined at entry.
        #    If entry defines x, then x is not live-in at entry?
        #    But example 2 says x IS live-in at entry.
        #    So the "implicit assignment" rule means:
        #    When checking "no node ... holds a def/upd", ignore the implicit assignment at entry if x is param.
        #    So entry is NOT in Def_x for liveness check if x in params.

        # Corrected Def_x for liveness
        Def_x_live = set()
        for node, instrs in reachable_blocks.items():
            for op, name in instrs:
                if name == x and op in ('def', 'upd'):
                    Def_x_live.add(node)

        # If x is param, entry is not a blocker
        if x in params:
            if entry in Def_x_live:
                Def_x_live.remove(entry)

        # Identify upward exposed uses for liveness
        Use_x_live = set()
        for node, instrs in reachable_blocks.items():
            seen_def = False
            for op, name in instrs:
                if name == x:
                    if op in ('def', 'upd'):
                        seen_def = True
                    if op == 'use' and not seen_def:
                        Use_x_live.add(node)
                    if op == 'upd' and not seen_def:
                        Use_x_live.add(node)

        live_x = set()
        q = deque(Use_x_live)
        visited_L = set(Use_x_live)
        while q:
            u = q.popleft()
            for v in rev_adj[u]:
                if v not in visited_L:
                    # Check if v defines x (and blocks)
                    if v in Def_x_live:
                        # If v defines x, it blocks propagation from v to predecessors.
                        # But v itself might be live if it has upward exposed use.
                        # If v is in Use_x_live, it's already visited.
                        # If v is not in Use_x_live, it's not live.
                        # So we just don't add it.
                        pass
                    else:
                        visited_L.add(v)
                        q.append(v)
        live_x = visited_L

        # Intersection
        phi_nodes = P_x & live_x
        if phi_nodes:
            if x not in phi_by_node:
                phi_by_node[x] = set()
            phi_by_node[x].update(phi_nodes)

    # Format output
    result = []
    node_phis = {}
    for x, nodes in phi_by_node.items():
        for node in nodes:
            if node not in node_phis:
                node_phis[node] = []
            node_phis[node].append(x)

    for node in sorted(node_phis.keys()):
        result.append((node, sorted(node_phis[node])))

    return result

