    return result

def format_sigfigs(s, sig, mode):
    if not isinstance(sig, int) or isinstance(sig, bool):
        raise ValueError("sig invalid")
    if sig < 1 or sig > 2000:
        raise ValueError("sig out of range")
    valid_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"
    }
    if mode not in valid_modes:
        raise ValueError("mode invalid")
    if not isinstance(s, str):
        raise ValueError("s invalid")
    if len(s) > 100000:
        raise ValueError("s too long")

    # Parse s
    sign = 1
    idx = 0
    if s[0] in '+-':
        sign = -1 if s[0] == '-' else 1
        idx = 1
    if idx >= len(s):
        raise ValueError("no digits")

    dot_idx = -1
    e_idx = -1
    for i in range(idx, len(s)):
        if s[i] == '.':
            dot_idx = i
        elif s[i] in 'eE':
            e_idx = i
            break

    if e_idx != -1:
        int_frac = s[idx:e_idx]
        exp_str = s[e_idx+1:]
    else:
        int_frac = s[idx:]
        exp_str = "0"

    if not int_frac:
        raise ValueError("no digits in int/frac")

    exp_sign = 1
    exp_idx = 0
    if exp_str[0] in '+-':
        exp_sign = -1 if exp_str[0] == '-' else 1
        exp_idx = 1
    if exp_idx >= len(exp_str) or not exp_str[exp_idx:].isdigit():
        raise ValueError("invalid exponent")
    exp_val = int(exp_str[exp_idx:]) * exp_sign

    digits = int_frac.replace('.', '')
    if not digits or not digits.isdigit():
        raise ValueError("invalid digits")

    int_part_len = dot_idx - idx if dot_idx != -1 else len(int_frac)

    # Find first non-zero
    first_nz = -1
    for i, c in enumerate(digits):
        if c != '0':
            first_nz = i
            break
    if first_nz == -1:
        return f"{'.' + '0'*(sig-1) if sig>1 else ''}e+00"

    digits = digits[first_nz:]
    first_digit_exp = exp_val + int_part_len - 1 - first_nz

    # Determine kept and dropped
    if sig >= len(digits):
        kept = digits
    else:
        kept = digits[:sig]
        dropped = digits[sig:]
        is_nonzero_dropped = any(c != '0' for c in dropped)
        round_up = False

        if mode == "toward_zero":
            round_up = False
        elif mode == "away_zero":
            round_up = is_nonzero_dropped
        elif mode == "toward_neg":
            round_up = (sign == -1 and is_nonzero_dropped)
        elif mode == "toward_pos":
            round_up = (sign == 1 and is_nonzero_dropped)
        elif mode in ("nearest_even", "nearest_away", "nearest_zero"):
