        raise ValueError
    valid_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"
    }
    if mode not in valid_modes:
        raise ValueError

    # Parse s
    i = 0
    sign_char = ''
    if i < len(s) and s[i] in '+-':
        sign_char = s[i]
        i += 1
    if i >= len(s):
        raise ValueError

    # Find dot and exponent
    dot_pos = -1
    e_pos = -1
    for j in range(i, len(s)):
        if s[j] == '.':
            if dot_pos != -1:
                raise ValueError
            dot_pos = j
        elif s[j] in 'eE':
            if e_pos != -1:
                raise ValueError
            e_pos = j

    # Extract parts
    mantissa_str = s[i:dot_pos if dot_pos != -1 else e_pos if e_pos != -1 else len(s)]
    if '.' in mantissa_str:
        raise ValueError # Should not happen with above logic but safety

    if dot_pos != -1:
        frac_str = s[dot_pos+1 : e_pos if e_pos != -1 else len(s)]
    else:
        frac_str = ''

    if e_pos != -1:
        exp_part = s[e_pos+1:]
        if len(exp_part) == 0:
            raise ValueError
        exp_sign = 1
        if exp_part[0] in '+-':
            exp_sign = 1 if exp_part[0] == '+' else -1
            exp_part = exp_part[1:]
        if len(exp_part) == 0 or not exp_part.isdigit():
            raise ValueError
        if len(exp_part) > 10:
            raise ValueError
        e_val = int(exp_part) * exp_sign
    else:
        e_val = 0

    # Validate digits
    if not mantissa_str.isdigit() or not frac_str.isdigit():
        raise ValueError
    if len(mantissa_str) == 0 and len(frac_str) == 0:
        raise ValueError

    # Combine digits
    all_digits = mantissa_str + frac_str
    # Remove leading zeros for value calculation, but keep track of position
    # Actually, we just need the integer value and the exponent shift from the dot
    num_leading_zeros = len(all_digits) - len(all_digits.lstrip('0'))
    if all_digits.lstrip('0') == '':
        M = 0
    else:
        M = int(all_digits.lstrip('0'))

    # Calculate total exponent
    # Value = M * 10^(e_val + num_digits_before_dot - 1 - num_digits_after_dot)
    # num_digits_before_dot = len(mantissa_str)
    # num_digits_after_dot = len(frac_str)
    E = e_val + len(mantissa_str) - 1 - len(frac_str)
    if num_leading_zeros > 0:
        E -= num_leading_zeros

    # Handle zero
    if M == 0:
        exp_str = f"{0:+02}"
        if sig == 1:
            return f"0e{exp_str}"
        else:
            return f"0.{'0' * (sig - 1)}e{exp_str}"

