    val_sign = -1 if sign_char == '-' else 1
    val = val_sign * M

    # Number of significant digits in val
    N = len(str(abs(val)))

    # If sig >= N, no rounding needed, just pad/format
    if sig >= N:
        str_val = str(abs(val)).zfill(sig)
        # Adjust exponent if we padded? No, exponent is based on first digit position.
        # First digit is at index 0 of str_val. Its place value is 10^(E + N - 1)
        # We want output exponent to be E + N - 1.
        out_exp = E + N - 1
        if out_exp < -999999999 or out_exp > 999999999:
            raise ValueError
        exp_str = f"{out_exp:+02}"
        if sig == 1:
            mant = str_val[0]
        else:
            mant = str_val[0] + '.' + str_val[1:]
        return f"{'-' if val < 0 else ''}{mant}e{exp_str}"

    # Rounding needed
    shift = N - sig
    divisor = 10 ** shift
    q, r = divmod(val, divisor)

    # Determine rounded value
    if r == 0:
        res = q
    elif 2 * r < divisor:
        res = q if val >= 0 else q + 1
    elif 2 * r > divisor:
        res = q + 1 if val >= 0 else q
    else: # Tie
        if mode == 'nearest_even':
            res = q if q % 2 == 0 else q + 1
        elif mode == 'nearest_away':
            res = q + 1
        elif mode == 'nearest_zero':
            res = q if val >= 0 else q + 1
        elif mode == 'toward_zero':
            res = q if val >= 0 else q + 1
        elif mode == 'away_zero':
            res = q + 1 if val >= 0 else q
        elif mode == 'toward_neg':
            res = q
        elif mode == 'toward_pos':
            res = q + 1
        elif mode == 'zero_five':
            res = q + 1 if abs(q) % 10 in (0, 5) else q
        else:
            raise ValueError # Should not happen

    # Handle carry (e.g., 99 -> 100)
    str_res = str(abs(res))
    if len(str_res) > sig:
        res //= 10
        E += 1
        str_res = str(abs(res))

    out_exp = E + len(str_res) - 1
    if out_exp < -999999999 or out_exp > 999999999:
        raise ValueError

    exp_str = f"{out_exp:+02}"
    if sig == 1:
        mant = str_res[0]
    else:
        mant = str_res[0] + '.' + str_res[1:]

    return f"{'-' if res < 0 else ''}{mant}e{exp_str}"

