    # Value = int(raw_digits) * 10^(exp_from_e - frac_digits_count)
    # Let L = len(raw_digits)
    # int(raw_digits) has L digits. Its MSB is at 10^(L-1).
    # So Value = (d_0...d_{L-1}) * 10^(L-1) * 10^(exp_from_e - frac_digits_count)
    #          = (d_0...d_{L-1}) * 10^(L-1 + exp_from_e - frac_digits_count)
    # In scientific notation d_0 . d_1 ... * 10^E
