        if not isinstance(s, str):
            raise ValueError("Input must be a string")
        if len(s) > 4000:
            raise ValueError("Input too long")

        sign = 1
        if s[0] == '+':
            s = s[1:]
        elif s[0] == '-':
            sign = -1
            s = s[1:]

        if not s:
            raise ValueError("No digits")

        core = s
        dot_idx = core.find('.')
        exp_idx = -1
        for i, c in enumerate(core):
            if c in 'eE':
                exp_idx = i
                break

        if dot_idx != -1:
            int_str = core[:dot_idx]
            frac_str = core[dot_idx+1:]
        else:
            int_str = core
            frac_str = ""

