        if exp_idx != -1:
            exp_part = core[exp_idx+1:]
            if not exp_part:
                raise ValueError("Empty exponent")
            exp_sign = 1
            if exp_part[0] == '+':
                exp_part = exp_part[1:]
            elif exp_part[0] == '-':
                exp_sign = -1
                exp_part = exp_part[1:]
            if not exp_part.isdigit():
                raise ValueError("Invalid exponent")
            if len(exp_part) > 10:
                raise ValueError("Exponent too long")
            E_exp = exp_sign * int(exp_part)

        if not int_str and not frac_str:
            raise ValueError("No digits")

        M = int(int_str + frac_str)
        E = -len(frac_str) + E_exp

        # Normalize to canonical m, e
        while M > 0 and M % 10 == 0 and E < 0:
            M //= 10
            E += 1

        d = max(0, -E)
        return M, E, d, sign

    Mx, Ex, _, sign_x = parse_decimal(x)
    Ms, Es, d, sign_s = parse_decimal(step)

    if sign_s == -1:
        raise ValueError("Step must be positive")
    if Ms == 0:
        raise ValueError("Step cannot be zero")

    # Compute ratio = |x| / step as abs_num / abs_den
    shift = Ex - Es
    if shift >= 0:
        abs_num = abs(Mx) * (10 ** shift)
        abs_den = abs(Ms)
    else:
        abs_num = abs(Mx)
        abs_den = abs(Ms) * (10 ** (-shift))

    q, r = divmod(abs_num, abs_den)

    if r == 0:
        abs_k = q
    else:
        # Determine abs_k based on mode
        if mode == "floor":
            abs_k = q if sign_x >= 0 else q + 1
        elif mode == "ceil":
            abs_k = q + 1 if sign_x >= 0 else q
        elif mode in ("outward", "tie_away"):
