                else: k = q
        elif mode == "tie_zero":
            if 2*r < den: k = q
            elif 2*r > den: k = q + 1
            else:
                if q >= 0: k = q
                else: k = q + 1

    R = k * Ms
    abs_R = abs(R)
    str_R = str(abs_R)

    if d == 0:
