    if mode not in ("floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"):
        raise ValueError("Invalid mode")

    def parse(s):
        if not s:
            raise ValueError
        idx = 0
        sign = 1
        if s[idx] in '+-':
            sign = 1 if s[idx] == '+' else -1
            idx += 1
        dot_idx = s.find('.', idx)
        e_idx = -1
        for i in range(idx, len(s)):
            if s[i] in 'eE':
                e_idx = i
                break
        mant_str = s[idx:e_idx] if e_idx != -1 else s[idx:]
        if not mant_str or (dot_idx != -1 and mant_str == '.'):
            raise ValueError
        digits = mant_str.replace('.', '')
        if not digits.isdigit():
            raise ValueError
        if dot_idx != -1:
            dot_in_mant = dot_idx - idx
            frac_digits = len(mant_str) - dot_in_mant - 1
        else:
            frac_digits = 0
        exp = 0
        if e_idx != -1:
            exp_str = s[e_idx+1:]
            if not exp_str:
                raise ValueError
            exp_sign = 1
            e2 = 0
            if exp_str[0] in '+-':
                exp_sign = 1 if exp_str[0] == '+' else -1
                e2 = 1
            exp_val = exp_str[e2:]
            if not exp_val or not exp_val.isdigit() or len(exp_val) > 10:
                raise ValueError
            exp = exp_sign * int(exp_val)
        scale = frac_digits - exp
        num = int(digits)
        return sign, num, scale

    sx, nx, scale_x = parse(x)
    ss, ns, scale_s = parse(step)
    if ss != 1 or ns == 0:
        raise ValueError("Step must be strictly positive")

    # Normalize step to canonical m, e, d
    # step = ns * 10^(-scale_s)
    # We want step = m * 10^e, m % 10 != 0
    while ns > 0 and ns % 10 == 0:
        ns //= 10
        scale_s -= 1
    # d = max(0, -e) where e = -scale_s => d = max(0, scale_s)
    d = max(0, scale_s)
    if d > 3000:
        raise ValueError("Step implies output too large")

    # Compute ratio x / step = sx * (nx * 10^(scale_s - scale_x)) / ns
    exp_diff = scale_s - scale_x
    if exp_diff >= 0:
        num = nx * (10 ** exp_diff)
    else:
        num = nx
    den = ns * (10 ** (-exp_diff) if exp_diff < 0 else 1)

    q, r = divmod(num, den)
    if sx == 1:
        k_low = q
        k_high = q + 1 if r > 0 else q
    else:
        k_low = -q - 1 if r > 0 else -q
        k_high = -q

    if r == 0:
        k = k_low
    else:
        d_low = r
        d_high = den - r
        if d_low < d_high:
            k = k_low
        elif d_low > d_high:
            k = k_high
        else:
            # Tie
            if mode == "tie_even":
                k = k_low if k_low % 2 == 0 else k_high
            elif mode == "tie_odd":
                k = k_low if k_low % 2 != 0 else k_high
            elif mode == "tie_away":
                k = k_low if abs(k_low) > abs(k_high) else k_high
            elif mode == "tie_zero":
                k = k_low if abs(k_low) < abs(k_high) else k_high

    # Compute result = k * step = k * ns * 10^(-scale_s)
    res_num = k * ns
    if res_num == 0:
        return "0"

    sign_str = "-" if res_num < 0 else ""
    abs_res = abs(res_num)

    # Format with d fractional digits
    if d == 0:
        int_part = str(abs_res)
        frac_part = ""
    else:
        s_abs = str(abs_res)
        if len(s_abs) <= d:
            int_part = "0"
            frac_part = s_abs.zfill(d)
        else:
            frac_part = s_abs[-d:]
            int_part = s_abs[:-d]

    if len(int_part) + d > 3000:
        raise ValueError("Output exceeds 3000 digits")

    if d == 0:
        return sign_str + int_part
    else:
        return sign_str + int_part + "." + frac_part

