    valid_modes = {"floor", "ceil", "outward", "inward", 
                   "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    def parse(s):
        m = re.match(r'^([+-])?(\d+\.?\d*|\.\d+)([eE]([+-]?\d{1,10}))?$', s)
        if not m:
            raise ValueError("Invalid decimal format")
        sign_str = m.group(1)
        num_part = m.group(2)
        exp_part = m.group(4)
        if '.' in num_part:
            ip, fp = num_part.split('.', 1)
        else:
            ip, fp = num_part, ""
        digits = ip + fp
        M = int(digits)
        frac_len = len(fp)
        exp_val = int(exp_part) if exp_part else 0
        E = exp_val - frac_len
        sign = 1 if (sign_str is None or sign_str == '+') else -1
        return sign, M, E

    sx, Mx, Ex = parse(x)
    ss, Ms, Es = parse(step)

    if ss != 1 or Ms == 0:
        raise ValueError("Step must be strictly greater than zero")

    # Canonicalize step: remove trailing zeros
    while Es > 0 and Ms % 10 == 0:
        Ms //= 10
        Es -= 1
    while Es < 0 and Ms % 10 == 0:
        Ms //= 10
        Es += 1
    d = max(0, -Es)

    if d > 3000:
        raise ValueError("Output exceeds 3000 digit limit")

    diff = Ex - Es

    # Compute q = floor(x/step) and r = remainder, handling huge exponents safely
    if diff >= 0:
        if Mx == 0:
            q, r = 0, 0
        elif diff > 3500:
            raise ValueError("Output exceeds 3000 digit limit")
        else:
            num = sx * Mx * (10 ** diff)
            den = Ms
            q, r = divmod(num, den)
    else:
        if -diff > 4000:
            q, r = 0, sx * Mx
        else:
            num = sx * Mx
            den = Ms * (10 ** (-diff))
            q, r = divmod(num, den)

    # Determine k based on mode
    if mode in ("floor", "ceil", "outward", "inward"):
        if mode == "floor":
            k = q
        elif mode == "ceil":
            k = q + 1
        elif mode == "outward":
            k = q + 1 if num >= 0 else q
        else: # inward
            k = q if num >= 0 else q + 1
    else:
        # tie_* modes: round to nearest, with tie-breaking
        if 2 * r < den:
            k = q
        elif 2 * r > den:
            k = q + 1
        else:
            # Tie
            if mode == "tie_even":
                k = q if q % 2 == 0 else q + 1
            elif mode == "tie_odd":
                k = q + 1 if q % 2 == 0 else q
            elif mode == "tie_away":
                k = q + 1 if num >= 0 else q
            else: # tie_zero
                k = q if num >= 0 else q + 1

    R = k * Ms
    sign_r = -1 if R < 0 else 1
    abs_R = abs(R)

    if R == 0:
        res_str = "0"
    else:
        if d == 0:
            res_str = str(abs_R)
